import React from 'react';
import { Search, FolderKanban, Users, CheckSquare, BarChart3, Settings } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import {
  Dialog,
  DialogContent,
} from './ui/dialog';
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from './ui/command';

interface CommandPaletteProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

const CommandPalette: React.FC<CommandPaletteProps> = ({ open, onOpenChange }) => {
  const navigate = useNavigate();

  const commands = [
    { icon: FolderKanban, label: 'Go to Projects', path: '/app/projects' },
    { icon: Users, label: 'Go to CRM Leads', path: '/app/crm' },
    { icon: CheckSquare, label: 'Go to Tasks', path: '/app/tasks' },
    { icon: BarChart3, label: 'Go to Reports', path: '/app/reports' },
    { icon: Settings, label: 'Go to Settings', path: '/app/settings' },
    { icon: FolderKanban, label: 'Create New Project', path: '/app/projects' },
    { icon: Users, label: 'Create New Lead', path: '/app/crm' },
    { icon: CheckSquare, label: 'Create New Task', path: '/app/tasks' },
  ];

  const handleSelect = (path: string) => {
    navigate(path);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="p-0 max-w-2xl">
        <Command className="rounded-lg border-0">
          <CommandInput 
            placeholder="Search or type a command..." 
            className="text-foreground"
          />
          <CommandList>
            <CommandEmpty className="text-muted-foreground py-6 text-center">
              No results found.
            </CommandEmpty>
            <CommandGroup heading="Navigation" className="text-muted-foreground">
              {commands.slice(0, 5).map((command) => {
                const Icon = command.icon;
                return (
                  <CommandItem
                    key={command.label}
                    onSelect={() => handleSelect(command.path)}
                    className="text-foreground"
                  >
                    <Icon className="w-4 h-4 mr-3 text-primary" />
                    {command.label}
                  </CommandItem>
                );
              })}
            </CommandGroup>
            <CommandGroup heading="Actions" className="text-muted-foreground">
              {commands.slice(5).map((command) => {
                const Icon = command.icon;
                return (
                  <CommandItem
                    key={command.label}
                    onSelect={() => handleSelect(command.path)}
                    className="text-foreground"
                  >
                    <Icon className="w-4 h-4 mr-3 text-primary" />
                    {command.label}
                  </CommandItem>
                );
              })}
            </CommandGroup>
          </CommandList>
        </Command>
      </DialogContent>
    </Dialog>
  );
};

export default CommandPalette;

import React, { useState, useEffect } from 'react';
import { useGoogleApi, CalendarEvent, NewCalendarEvent } from '../contexts/GoogleApiContext';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from './ui/dialog';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Label } from './ui/label';
import { Textarea } from './ui/textarea';
import { Badge } from './ui/badge';
import {
  Calendar, Clock, MapPin, Users, Plus, Trash2, Loader2, ExternalLink,
  Cloud, CloudOff,
} from 'lucide-react';
import { useToast } from '../hooks/use-toast';

// ΓöÇΓöÇ Calendar Events List ΓöÇΓöÇ
interface CalendarEventsProps {
  compact?: boolean;
}

export const CalendarEventsList: React.FC<CalendarEventsProps> = ({ compact = false }) => {
  const { isConnected, isLoading: apiLoading, connectGoogle, listCalendarEvents, deleteCalendarEvent } = useGoogleApi();
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [loading, setLoading] = useState(false);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const { toast } = useToast();

  const loadEvents = async () => {
    if (!isConnected) return;
    setLoading(true);
    try {
      const result = await listCalendarEvents();
      setEvents(result);
    } catch (err) {
      console.error('Error loading calendar events:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (isConnected) loadEvents();
  }, [isConnected]);

  const handleDelete = async (eventId: string) => {
    try {
      await deleteCalendarEvent(eventId);
      setEvents(prev => prev.filter(e => e.id !== eventId));
      toast({ title: 'Ngjarja u fshi' });
    } catch {
      toast({ title: 'Gabim gjat├½ fshirjes', variant: 'destructive' });
    }
  };

  if (!isConnected) {
    return (
      <div className="flex flex-col items-center justify-center py-8 gap-3">
        <CloudOff className="w-10 h-10 text-muted-foreground" />
        <p className="text-sm text-muted-foreground">Lidhu me Google Calendar</p>
        <Button size="sm" onClick={connectGoogle} disabled={apiLoading} className="bg-blue-600 hover:bg-blue-700 text-white">
          {apiLoading ? <Loader2 className="w-3.5 h-3.5 mr-1.5 animate-spin" /> : <Cloud className="w-3.5 h-3.5 mr-1.5" />}
          Lidhu
        </Button>
      </div>
    );
  }

  const formatEventTime = (event: CalendarEvent) => {
    const start = event.start.dateTime || event.start.date;
    const end = event.end.dateTime || event.end.date;
    if (!start) return '';
    const d = new Date(start);
    const dateStr = d.toLocaleDateString('sq-AL', { day: 'numeric', month: 'short' });
    if (!event.start.dateTime) return dateStr; // All-day event
    const timeStr = d.toLocaleTimeString('sq-AL', { hour: '2-digit', minute: '2-digit' });
    if (end) {
      const endTime = new Date(end).toLocaleTimeString('sq-AL', { hour: '2-digit', minute: '2-digit' });
      return `${dateStr} ┬╖ ${timeStr} ΓÇô ${endTime}`;
    }
    return `${dateStr} ┬╖ ${timeStr}`;
  };

  const isToday = (event: CalendarEvent) => {
    const start = event.start.dateTime || event.start.date;
    if (!start) return false;
    const d = new Date(start);
    const now = new Date();
    return d.toDateString() === now.toDateString();
  };

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        {!compact && <h3 className="text-sm font-semibold">Ngjarjet e ardhshme</h3>}
        <Button size="sm" variant="outline" onClick={() => setShowCreateDialog(true)}>
          <Plus className="w-3.5 h-3.5 mr-1" />
          Shto Takim
        </Button>
      </div>

      {loading ? (
        <div className="flex justify-center py-6">
          <Loader2 className="w-5 h-5 animate-spin text-muted-foreground" />
        </div>
      ) : events.length === 0 ? (
        <div className="text-center py-6">
          <Calendar className="w-8 h-8 text-muted-foreground mx-auto mb-2" />
          <p className="text-xs text-muted-foreground">Asnj├½ ngjarje e ardhshme</p>
        </div>
      ) : (
        <div className="space-y-1.5">
          {events.slice(0, compact ? 5 : 20).map(event => (
            <div
              key={event.id}
              className={`flex items-start gap-3 p-2.5 rounded-lg border transition-colors group ${
                isToday(event) ? 'bg-primary/5 border-primary/20' : 'hover:bg-muted'
              }`}
            >
              <div className={`w-1 self-stretch rounded-full flex-shrink-0 ${
                isToday(event) ? 'bg-primary' : 'bg-muted-foreground/30'
              }`} />
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium truncate">{event.summary || '(Pa titull)'}</p>
                <div className="flex items-center gap-2 mt-0.5 text-[11px] text-muted-foreground">
                  <Clock className="w-3 h-3 flex-shrink-0" />
                  <span>{formatEventTime(event)}</span>
                </div>
                {event.location && (
                  <div className="flex items-center gap-2 mt-0.5 text-[11px] text-muted-foreground">
                    <MapPin className="w-3 h-3 flex-shrink-0" />
                    <span className="truncate">{event.location}</span>
                  </div>
                )}
                {event.attendees && event.attendees.length > 0 && (
                  <div className="flex items-center gap-1 mt-1">
                    <Users className="w-3 h-3 text-muted-foreground" />
                    <span className="text-[11px] text-muted-foreground">
                      {event.attendees.length} pjes├½marr├½s
                    </span>
                  </div>
                )}
              </div>
              <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                {event.htmlLink && (
                  <a
                    href={event.htmlLink}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="p-1 hover:bg-muted rounded"
                  >
                    <ExternalLink className="w-3.5 h-3.5 text-muted-foreground" />
                  </a>
                )}
                <button onClick={() => handleDelete(event.id)} className="p-1 hover:bg-destructive/10 rounded">
                  <Trash2 className="w-3.5 h-3.5 text-destructive" />
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      <CreateEventDialog
        open={showCreateDialog}
        onOpenChange={setShowCreateDialog}
        onCreated={() => loadEvents()}
      />
    </div>
  );
};

// ΓöÇΓöÇ Create Calendar Event Dialog ΓöÇΓöÇ
interface CreateEventDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onCreated: () => void;
  prefillTitle?: string;
  prefillAttendees?: string[];
  prefillDate?: string;
}

export const CreateEventDialog: React.FC<CreateEventDialogProps> = ({
  open,
  onOpenChange,
  onCreated,
  prefillTitle = '',
  prefillAttendees = [],
  prefillDate,
}) => {
  const { createCalendarEvent } = useGoogleApi();
  const { toast } = useToast();
  const [saving, setSaving] = useState(false);

  const [form, setForm] = useState({
    summary: prefillTitle,
    description: '',
    location: '',
    date: prefillDate || new Date().toISOString().split('T')[0],
    startTime: '10:00',
    endTime: '11:00',
    attendeeEmail: '',
    attendees: prefillAttendees,
  });

  useEffect(() => {
    if (open) {
      setForm(prev => ({
        ...prev,
        summary: prefillTitle,
        attendees: prefillAttendees,
        date: prefillDate || new Date().toISOString().split('T')[0],
      }));
    }
  }, [open, prefillTitle, prefillAttendees, prefillDate]);

  const addAttendee = () => {
    const email = form.attendeeEmail.trim();
    if (email && !form.attendees.includes(email)) {
      setForm(prev => ({ ...prev, attendees: [...prev.attendees, email], attendeeEmail: '' }));
    }
  };

  const removeAttendee = (email: string) => {
    setForm(prev => ({ ...prev, attendees: prev.attendees.filter(e => e !== email) }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.summary.trim()) return;

    setSaving(true);
    try {
      const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
      const event: NewCalendarEvent = {
        summary: form.summary,
        description: form.description || undefined,
        location: form.location || undefined,
        start: { dateTime: `${form.date}T${form.startTime}:00`, timeZone: tz },
        end: { dateTime: `${form.date}T${form.endTime}:00`, timeZone: tz },
        attendees: form.attendees.length > 0 ? form.attendees.map(e => ({ email: e })) : undefined,
        reminders: { useDefault: false, overrides: [{ method: 'popup', minutes: 30 }] },
      };
      await createCalendarEvent(event);
      toast({ title: 'Takimi u shtua n├½ Google Calendar!' });
      onCreated();
      onOpenChange(false);
    } catch (err: any) {
      toast({ title: 'Gabim', description: err.message, variant: 'destructive' });
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Calendar className="w-5 h-5 text-blue-500" />
            Shto Takim
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label>Titulli *</Label>
            <Input
              value={form.summary}
              onChange={e => setForm(prev => ({ ...prev, summary: e.target.value }))}
              placeholder="psh. Takim me klientin"
              required
            />
          </div>

          <div className="grid grid-cols-3 gap-3">
            <div className="space-y-2">
              <Label>Data</Label>
              <Input
                type="date"
                value={form.date}
                onChange={e => setForm(prev => ({ ...prev, date: e.target.value }))}
              />
            </div>
            <div className="space-y-2">
              <Label>Fillimi</Label>
              <Input
                type="time"
                value={form.startTime}
                onChange={e => setForm(prev => ({ ...prev, startTime: e.target.value }))}
              />
            </div>
            <div className="space-y-2">
              <Label>Mbarimi</Label>
              <Input
                type="time"
                value={form.endTime}
                onChange={e => setForm(prev => ({ ...prev, endTime: e.target.value }))}
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label>Vendndodhja</Label>
            <Input
              value={form.location}
              onChange={e => setForm(prev => ({ ...prev, location: e.target.value }))}
              placeholder="Google Meet, Zyr├½, etj."
            />
          </div>

          <div className="space-y-2">
            <Label>P├½rshkrimi</Label>
            <Textarea
              value={form.description}
              onChange={e => setForm(prev => ({ ...prev, description: e.target.value }))}
              placeholder="Sh├½nime shtes├½..."
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label>Pjes├½marr├½sit</Label>
            <div className="flex gap-2">
              <Input
                type="email"
                value={form.attendeeEmail}
                onChange={e => setForm(prev => ({ ...prev, attendeeEmail: e.target.value }))}
                placeholder="email@shembull.com"
                onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); addAttendee(); } }}
              />
              <Button type="button" variant="outline" size="sm" onClick={addAttendee}>
                <Plus className="w-4 h-4" />
              </Button>
            </div>
            {form.attendees.length > 0 && (
              <div className="flex flex-wrap gap-1.5 mt-1">
                {form.attendees.map(email => (
                  <Badge
                    key={email}
                    variant="secondary"
                    className="text-xs cursor-pointer hover:bg-destructive/10"
                    onClick={() => removeAttendee(email)}
                  >
                    {email} ├ù
                  </Badge>
                ))}
              </div>
            )}
          </div>

          <div className="flex justify-end gap-2 pt-2">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Anulo
            </Button>
            <Button type="submit" disabled={saving || !form.summary.trim()} className="bg-blue-600 hover:bg-blue-700 text-white">
              {saving ? <Loader2 className="w-4 h-4 mr-1.5 animate-spin" /> : <Calendar className="w-4 h-4 mr-1.5" />}
              Ruaj Takimin
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default CalendarEventsList;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCollection, useMutation } from '../hooks/useFirestore';
import { useAuth } from '../contexts/AuthContext';
import { Bell, Check, Trash2, Mail, Calendar, User, AlertCircle, CheckCircle, Info, ExternalLink } from 'lucide-react';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { ScrollArea } from './ui/scroll-area';
import { writeBatch, doc } from 'firebase/firestore';
import { db } from '../lib/firebase';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from './ui/dropdown-menu';
import { Tabs, TabsContent, TabsList, TabsTrigger } from './ui/tabs';
import type { Notification } from '../types';

const NotificationsCenter: React.FC = () => {
  const { user } = useAuth();
  const { data: notifications, loading: isPending } = useCollection<Notification>('notifications', {
    where: user ? [{ field: 'userId', operator: '==', value: user.uid }] : undefined,
    orderBy: { field: 'createdAt', direction: 'desc' },
  });

  const notificationMutation = useMutation<Notification>('notifications');

  const unreadCount = notifications?.filter(n => !n.isRead).length || 0;

  const handleMarkAsRead = async (id: string) => {
    await notificationMutation.update(id, { isRead: true });
  };

  const handleMarkAllAsRead = async () => {
    const unread = notifications?.filter(n => !n.isRead) || [];
    if (unread.length === 0) return;
    const batch = writeBatch(db);
    for (const notification of unread) {
      batch.update(doc(db, 'notifications', notification.id), { isRead: true });
    }
    await batch.commit();
  };

  const handleDelete = async (id: string) => {
    await notificationMutation.remove(id);
  };

  const getNotificationIcon = (title: string) => {
    // Task assignment (Albanian + English)
    if (title.includes('Caktuar') || title.includes('caktua') || title.includes('Assigned') || title.includes('Task')) return <User className="w-4 h-4 text-success" />;
    // Comments (Albanian + English)
    if (title.includes('Koment') || title.includes('Comment')) return <Mail className="w-4 h-4 text-info" />;
    // Deadlines / overdue (Albanian + English)
    if (title.includes('Afati') || title.includes('skaduara') || title.includes('Due')) return <AlertCircle className="w-4 h-4 text-warning" />;
    // Completed (Albanian + English)
    if (title.includes('P├½rfundua') || title.includes('Completed')) return <CheckCircle className="w-4 h-4 text-success" />;
    // Recurring tasks
    if (title.includes('periodike') || title.includes('Recurring')) return <Calendar className="w-4 h-4 text-primary" />;
    // Collaborator added
    if (title.includes('bashk├½pun├½tor') || title.includes('Collaborator')) return <User className="w-4 h-4 text-info" />;
    // Invoices
    if (title.includes('Fatur') || title.includes('Invoice')) return <Mail className="w-4 h-4 text-warning" />;
    return <Info className="w-4 h-4 text-muted-foreground" />;
  };

  const unreadNotifications = notifications?.filter(n => !n.isRead) || [];
  const readNotifications = notifications?.filter(n => n.isRead) || [];

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button 
          variant="ghost" 
          size="icon"
          className="bg-white/10 text-primary-foreground hover:bg-white/20 relative"
          aria-label="Notifications"
        >
          <Bell className="w-5 h-5" />
          {unreadCount > 0 && (
            <Badge 
              className="absolute -top-1 -right-1 h-5 w-5 flex items-center justify-center p-0 bg-accent text-accent-foreground text-xs"
            >
              {unreadCount > 9 ? '9+' : unreadCount}
            </Badge>
          )}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-[calc(100vw-2rem)] max-w-[400px] sm:w-[400px] p-0">
        <div className="p-4 border-b flex items-center justify-between">
          <h3 className="font-semibold text-foreground">Notifications</h3>
          {unreadCount > 0 && (
            <Button 
              variant="ghost" 
              size="sm" 
              onClick={handleMarkAllAsRead}
              className="text-xs"
            >
              <Check className="w-3 h-3 mr-1" />
              Mark all read
            </Button>
          )}
        </div>

        <Tabs defaultValue="unread" className="w-full">
          <TabsList className="w-full rounded-none border-b">
            <TabsTrigger value="unread" className="flex-1">
              Unread ({unreadCount})
            </TabsTrigger>
            <TabsTrigger value="all" className="flex-1">
              All ({notifications?.length || 0})
            </TabsTrigger>
          </TabsList>

          <TabsContent value="unread" className="m-0">
            <ScrollArea className="max-h-[60vh] sm:max-h-[400px]">
              {isPending ? (
                <div className="p-8 text-center text-muted-foreground">
                  Loading notifications...
                </div>
              ) : unreadNotifications.length === 0 ? (
                <div className="p-8 text-center text-muted-foreground">
                  <Bell className="w-12 h-12 mx-auto mb-2 opacity-20" />
                  <p>No unread notifications</p>
                </div>
              ) : (
                <div className="divide-y">
                  {unreadNotifications.map(notification => (
                    <NotificationItem
                      key={notification.id}
                      notification={notification}
                      onMarkAsRead={handleMarkAsRead}
                      onDelete={handleDelete}
                      getIcon={getNotificationIcon}
                    />
                  ))}
                </div>
              )}
            </ScrollArea>
          </TabsContent>

          <TabsContent value="all" className="m-0">
            <ScrollArea className="max-h-[60vh] sm:max-h-[400px]">
              {isPending ? (
                <div className="p-8 text-center text-muted-foreground">
                  Loading notifications...
                </div>
              ) : notifications?.length === 0 ? (
                <div className="p-8 text-center text-muted-foreground">
                  <Bell className="w-12 h-12 mx-auto mb-2 opacity-20" />
                  <p>No notifications yet</p>
                </div>
              ) : (
                <div className="divide-y">
                  {notifications?.map(notification => (
                    <NotificationItem
                      key={notification.id}
                      notification={notification}
                      onMarkAsRead={handleMarkAsRead}
                      onDelete={handleDelete}
                      getIcon={getNotificationIcon}
                    />
                  ))}
                </div>
              )}
            </ScrollArea>
          </TabsContent>
        </Tabs>
      </DropdownMenuContent>
    </DropdownMenu>
  );
};

const NotificationItem: React.FC<{
  notification: Notification;
  onMarkAsRead: (id: string) => void;
  onDelete: (id: string) => void;
  getIcon: (title: string) => React.ReactNode;
}> = ({ notification, onMarkAsRead, onDelete, getIcon }) => {
  const navigate = useNavigate();
  const timeAgo = (date: Date) => {
    const seconds = Math.floor((new Date().getTime() - new Date(date).getTime()) / 1000);
    
    if (seconds < 60) return 'just now';
    if (seconds < 3600) return `${Math.floor(seconds / 60)}m ago`;
    if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ago`;
    if (seconds < 604800) return `${Math.floor(seconds / 86400)}d ago`;
    return new Date(date).toLocaleDateString();
  };

  const handleAction = () => {
    const n = notification as any;
    if (n.actionType === 'navigate' && n.actionUrl) {
      navigate(n.actionUrl);
      if (!notification.isRead) onMarkAsRead(notification.id);
    }
  };

  const actionLabel = (notification as any).actionLabel;
  const actionUrl = (notification as any).actionUrl;

  return (
    <div 
      className={`p-4 hover:bg-muted/50 transition-colors ${
        !notification.isRead ? 'bg-primary/5' : ''
      }`}
    >
      <div className="flex gap-3">
        <div className="flex-shrink-0 mt-1">
          {getIcon(notification.title)}
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-2">
            <div className="flex-1">
              <p className="font-medium text-sm text-foreground">
                {notification.title}
              </p>
              <p className="text-sm text-muted-foreground mt-1">
                {notification.message}
              </p>
              {actionUrl && actionLabel && (
                <Button
                  variant="outline"
                  size="sm"
                  className="mt-2 h-7 text-xs gap-1"
                  onClick={handleAction}
                >
                  <ExternalLink className="w-3 h-3" />
                  {actionLabel}
                </Button>
              )}
              <p className="text-xs text-muted-foreground mt-2">
                {timeAgo(notification.createdAt)}
              </p>
            </div>
            {!notification.isRead && (
              <div className="w-2 h-2 bg-primary rounded-full flex-shrink-0 mt-1" />
            )}
          </div>
        </div>
        <div className="flex gap-1 flex-shrink-0">
          {!notification.isRead && (
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8"
              onClick={() => onMarkAsRead(notification.id)}
            >
              <Check className="w-4 h-4" />
            </Button>
          )}
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8 text-error hover:text-error"
            onClick={() => onDelete(notification.id)}
          >
            <Trash2 className="w-4 h-4" />
          </Button>
        </div>
      </div>
    </div>
  );
};

