// Inspired by react-hot-toast library
import React from "react"

import type {
  ToastActionElement,
  ToastProps,
} from "@/components/ui/toast"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
      type: ActionType["ADD_TOAST"]
      toast: ToasterToast
    }
  | {
      type: ActionType["UPDATE_TOAST"]
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType["DISMISS_TOAST"]
      toastId?: ToasterToast["id"]
    }
  | {
      type: ActionType["REMOVE_TOAST"]
      toastId?: ToasterToast["id"]
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t
        ),
      }

    case "DISMISS_TOAST": {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

export { useToast, toast }

import { useEffect, useState, useRef, useCallback } from 'react';
import { useCollection } from './useFirestore';
import { useAuth } from '../contexts/AuthContext';
import { collection, addDoc, updateDoc, doc, Timestamp } from 'firebase/firestore';
import { db } from '../lib/firebase';
import type { ClientPortalAccess, Customer } from '../types';

/**
 * Hook that checks if the current authenticated user has client portal access.
 * Auto-links the userId if the user's email matches a portal access record.
 * Auto-creates Customer + portal access + Lead if user has no records yet.
 *
 * Uses direct Firestore writes (not useMutation) to avoid hook closure issues.
 */
export function useClientPortal() {
  const { user, loading: authLoading } = useAuth();
  const [autoCreating, setAutoCreating] = useState(false);
  const [autoCreated, setAutoCreated] = useState(false);
  const [createdCustomerId, setCreatedCustomerId] = useState<string | null>(null);
  const didAutoCreate = useRef(false);
  const didAutoLink = useRef(false);

  // Query portal access by userId only (single where = no composite index needed)
  const { data: byUserId, loading: byUserIdLoading } = useCollection<ClientPortalAccess>(
    'clientPortalAccess',
    user
      ? { where: [{ field: 'userId', operator: '==', value: user.uid }] }
      : undefined
  );

  // Query portal access by email (for unlinked records)
  const { data: byEmail, loading: byEmailLoading } = useCollection<ClientPortalAccess>(
    'clientPortalAccess',
    user?.email
      ? { where: [{ field: 'email', operator: '==', value: user.email }] }
      : undefined
  );

  // Check for matching customer by email
  const { data: matchingCustomers, loading: customersLoading } = useCollection<Customer>(
    'customers',
    user?.email
      ? { where: [{ field: 'email', operator: '==', value: user.email }], skipTeamFilter: true }
      : undefined
  );

  // Fetch team members to notify admins
  const { data: allTeamMembers } = useCollection<any>('teamMembers', {
    where: [{ field: 'status', operator: '==', value: 'Active' }],
  });

  // Filter to get only Active access records
  const activeByUserId = byUserId?.filter(a => a.status === 'Active') || [];
  const activeByEmail = byEmail?.filter(a => a.status === 'Active') || [];

  // Auto-link: if portal access exists by email but userId is empty, update it
  useEffect(() => {
    if (!user || byUserIdLoading || byEmailLoading || didAutoLink.current) return;
    if (activeByUserId.length > 0) return; // Already linked

    const emailMatch = activeByEmail.find(a => !a.userId || a.userId === '');
    if (emailMatch) {
      didAutoLink.current = true;
      updateDoc(doc(db, 'clientPortalAccess', emailMatch.id), {
        userId: user.uid,
        updatedAt: Timestamp.now(),
      }).catch(() => { didAutoLink.current = false; });
    }
  }, [user, activeByUserId, activeByEmail, byUserIdLoading, byEmailLoading]);

  // Direct Firestore create helper (avoids useMutation hook closure issues)
  const createDoc = useCallback(async (collName: string, data: Record<string, any>) => {
    const docData = Object.fromEntries(
      Object.entries({
        ...data,
        createdAt: Timestamp.now(),
        updatedAt: Timestamp.now(),
        createdByUserId: user?.uid || null,
      }).filter(([_, v]) => v !== undefined)
    );
    const ref = await addDoc(collection(db, collName), docData);
    return { id: ref.id, ...docData };
  }, [user?.uid]);

  // Auto-create: if no portal access exists, create Customer + Access + Lead
  useEffect(() => {
    if (!user?.email || authLoading || byUserIdLoading || byEmailLoading || customersLoading) return;
    if (autoCreating || didAutoCreate.current) return;
    if (activeByUserId.length > 0) return;
    if (activeByEmail.length > 0) return;

    const customer = matchingCustomers?.[0];

    if (customer) {
      // Customer exists but no Active portal access ΓÇö create access
      setAutoCreating(true);
      didAutoCreate.current = true;
      setCreatedCustomerId(customer.id);

      createDoc('clientPortalAccess', {
        customerId: customer.id,
        userId: user.uid,
        email: user.email,
        status: 'Active',
      }).then(() => {
        setAutoCreated(true);
        setAutoCreating(false);
      }).catch(() => {
        setAutoCreating(false);
        setCreatedCustomerId(null);
        didAutoCreate.current = false;
      });
    } else {
      // No customer at all ΓÇö create Customer + Access + Lead + Notify admins
      setAutoCreating(true);
      didAutoCreate.current = true;
      const displayName = user.displayName || user.email || 'Klient';

      createDoc('customers', {
        name: displayName,
        email: user.email,
        status: 'Pending',
      }).then(async (newCustomer) => {
        setCreatedCustomerId(newCustomer.id);

        // Create portal access
        await createDoc('clientPortalAccess', {
          customerId: newCustomer.id,
          userId: user.uid,
          email: user.email!,
          status: 'Active',
        });

        // Create Lead (so admin sees it in CRM)
        createDoc('leads', {
          name: displayName,
          email: user.email,
          status: 'New',
          source: 'Portal - Google Sign In',
        }).catch(() => { /* non-critical */ });

        // Notify admin team members
        const admins = allTeamMembers?.filter(
          (m: any) => m.role === 'Admin'
        ) || [];
        // Also check for team owners
        for (const admin of admins) {
          createDoc('notifications', {
            userId: admin.userId,
            type: 'new_client',
            title: 'Klient i ri u regjistrua',
            message: `${displayName} (${user.email}) u regjistrua n├½ portal.`,
            read: false,
          }).catch(() => { /* non-critical */ });
        }
      }).then(() => {
        setAutoCreated(true);
        setAutoCreating(false);
      }).catch(() => {
        setAutoCreating(false);
        setCreatedCustomerId(null);
        didAutoCreate.current = false;
      });
    }
  }, [user, authLoading, activeByUserId, activeByEmail, byUserIdLoading, byEmailLoading, matchingCustomers, customersLoading, autoCreating, createDoc, allTeamMembers]);

  const access = activeByUserId[0] || activeByEmail[0] || null;

  const resolvedCustomerId = access?.customerId
    || createdCustomerId
    || matchingCustomers?.[0]?.id
    || null;

  // Keep isLoading=true in the gap between "queries done" and "useEffect fires auto-create"
  const queriesLoaded = !byUserIdLoading && !byEmailLoading && !customersLoading;
  const hasNoAccess = activeByUserId.length === 0 && activeByEmail.length === 0;
  const pendingAutoCreate = !!user?.email && queriesLoaded && hasNoAccess && !autoCreating && !didAutoCreate.current;

  return {
    isClient: !!access || autoCreating || autoCreated,
    portalAccess: access,
    customerId: resolvedCustomerId,
    isLoading: authLoading || byUserIdLoading || byEmailLoading || autoCreating || pendingAutoCreate,
  };
}

import { useState, useEffect, useCallback, useMemo, useSyncExternalStore } from 'react';
import {
  collection,
  doc,
  addDoc,
  updateDoc,
  deleteDoc,
  query,
  where,
  orderBy,
  limit as firestoreLimit,
  onSnapshot,
  QueryConstraint,
  Timestamp,
  DocumentData
} from 'firebase/firestore';
import { db } from '../lib/firebase';
import { useAuth } from '../contexts/AuthContext';

// Types for query options
interface QueryOptions {
  where?: { field: string; operator: string; value: any }[];
  orderBy?: { field: string; direction?: 'asc' | 'desc' };
  skipTeamFilter?: boolean; // For portal views and hooks that handle their own scoping
  limit?: number; // Server-side limit for non-team-scoped collections (ignored for team-scoped)
}

// ---- Reactive global teamId for data isolation ----
let _globalTeamId: string | null = null;
let _teamIdListeners: (() => void)[] = [];

function _subscribeTeamId(listener: () => void) {
  _teamIdListeners = [..._teamIdListeners, listener];
  return () => {
    _teamIdListeners = _teamIdListeners.filter(l => l !== listener);
  };
}

function _getTeamIdSnapshot() {
  return _globalTeamId;
}

export function setGlobalTeamId(id: string | null) {
  if (_globalTeamId !== id) {
    _globalTeamId = id;
    for (const listener of _teamIdListeners) {
      listener();
    }
  }
}

export function getGlobalTeamId(): string | null {
  return _globalTeamId;
}

/** React hook to reactively read global teamId (triggers re-render on change) */
function useGlobalTeamId(): string | null {
  return useSyncExternalStore(_subscribeTeamId, _getTeamIdSnapshot);
}

// Collections that require teamId-based data isolation
const teamScopedCollections = new Set([
  'tasks', 'invoices', 'customers', 'leads', 'services',
  'expenses', 'goals', 'timeEntries', 'channels', 'messages',
  'activities', 'clientRequests', 'invoiceItems', 'taskComments',
  'taskCollaborators', 'customIndustries', 'typingIndicators',
  'directMessages', 'milestones', 'serviceInquiries', 'projectComments',
  'workspaceFolders', 'workspaceDriveFiles', 'projects',
]);

// Convert Firestore timestamps to Date
function convertTimestamps(data: DocumentData): DocumentData {
  const converted: DocumentData = { ...data };
  for (const key in converted) {
    if (converted[key] instanceof Timestamp) {
      converted[key] = converted[key].toDate();
    }
  }
  return converted;
}

// Hook to fetch a collection with real-time updates
// Auto-injects teamId filter for team-scoped collections (unless skipTeamFilter is set)
export function useCollection<T = DocumentData>(
  collectionName: string,
  options?: QueryOptions
) {
  const [data, setData] = useState<(T & { id: string })[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const reactiveTeamId = useGlobalTeamId();
  const isTeamScoped = teamScopedCollections.has(collectionName) && !options?.skipTeamFilter;

  // For non-team-scoped collections (teamMembers, teams, notifications, etc.) use a stable
  // null sentinel so that changes to globalTeamId don't cause their effects to re-run and
  // re-subscribe. This prevents a cascade where globalTeamId being set causes the
  // usePermissions Firestore subscriptions to recreate, which briefly re-evaluates permissions,
  // which can call setGlobalTeamId again, creating an oscillation loop.
  const globalTeamId = isTeamScoped ? reactiveTeamId : null;

  // Stable dependency keys to avoid excessive re-renders from new object references
  const whereKey = JSON.stringify(options?.where || null);
  const orderKey = JSON.stringify(options?.orderBy || null);
  const skipTeamFilter = options?.skipTeamFilter || false;

  useEffect(() => {
    // For team-scoped collections, don't query until teamId is available
    if (isTeamScoped && !globalTeamId) {
      setData([]);
      setLoading(true);
      return;
    }

    const constraints: QueryConstraint[] = [];

    // For team-scoped collections: fetch ALL docs, then filter client-side.
    // This ensures legacy documents (created before data-isolation, without teamId field)
    // still appear. Also avoids ALL composite index requirements.
    if (isTeamScoped && globalTeamId) {
      // No server-side constraints ΓÇö everything handled client-side
    } else {
      // Non-team-scoped: use all constraints server-side as before
      if (options?.where) {
        options.where.forEach((w) => {
          constraints.push(where(w.field, w.operator as any, w.value));
        });
      }
      if (options?.orderBy) {
        constraints.push(orderBy(options.orderBy.field, options.orderBy.direction || 'asc'));
      }
      if (options?.limit && options.limit > 0) {
        constraints.push(firestoreLimit(options.limit));
      }
    }

    const q = query(collection(db, collectionName), ...constraints);

    const unsubscribe = onSnapshot(
      q,
      (snapshot) => {
        let items = snapshot.docs.map((doc) => ({
          id: doc.id,
          ...convertTimestamps(doc.data())
        })) as (T & { id: string })[];

        // Client-side teamId filtering: include docs belonging to this team
        // OR legacy docs without teamId (created before data-isolation)
        if (isTeamScoped && globalTeamId) {
          items = items.filter(item => {
            const docTeamId = (item as any).teamId;
            return docTeamId === globalTeamId || !docTeamId;
          });
        }

        // Client-side where filtering for team-scoped collections
        if (isTeamScoped && globalTeamId && options?.where) {
          items = items.filter(item => {
            return options.where!.every(w => {
              const val = (item as any)[w.field];
              switch (w.operator) {
                case '==': return val === w.value;
                case '!=': return val !== w.value;
                case '<': return val < w.value;
                case '<=': return val <= w.value;
                case '>': return val > w.value;
                case '>=': return val >= w.value;
                case 'in': return Array.isArray(w.value) && w.value.includes(val);
                case 'not-in': return Array.isArray(w.value) && !w.value.includes(val);
                case 'array-contains': return Array.isArray(val) && val.includes(w.value);
                case 'array-contains-any': return Array.isArray(val) && Array.isArray(w.value) && w.value.some((v: any) => val.includes(v));
                default: return true;
              }
            });
          });
        }

        // Client-side sorting for team-scoped collections
        if (isTeamScoped && globalTeamId && options?.orderBy) {
          const field = options.orderBy.field;
          const dir = options.orderBy.direction || 'asc';
          items = [...items].sort((a, b) => {
            const va = (a as any)[field];
            const vb = (b as any)[field];
            if (va == null && vb == null) return 0;
            if (va == null) return 1;
            if (vb == null) return -1;
            const ta = va instanceof Date ? va.getTime() : typeof va === 'string' ? va : Number(va);
            const tb = vb instanceof Date ? vb.getTime() : typeof vb === 'string' ? vb : Number(vb);
            if (ta < tb) return dir === 'asc' ? -1 : 1;
            if (ta > tb) return dir === 'asc' ? 1 : -1;
            return 0;
          });
        }

        setData(items);
        setLoading(false);
      },
      (err) => {
        console.error(`Error fetching ${collectionName}:`, err);
        setError(err);
        setLoading(false);
      }
    );

    return () => unsubscribe();
  }, [collectionName, whereKey, orderKey, skipTeamFilter, globalTeamId]);

  return { data, loading, error };
}

// Hook to fetch a single document
export function useDocument<T = DocumentData>(
  collectionName: string,
  documentId: string | undefined
) {
  const [data, setData] = useState<(T & { id: string }) | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    if (!documentId) {
      setLoading(false);
      return;
    }

    const docRef = doc(db, collectionName, documentId);
    
    const unsubscribe = onSnapshot(
      docRef,
      (snapshot) => {
        if (snapshot.exists()) {
          setData({
            id: snapshot.id,
            ...convertTimestamps(snapshot.data())
          } as T & { id: string });
        } else {
          setData(null);
        }
        setLoading(false);
      },
      (err) => {
        console.error(`Error fetching document:`, err);
        setError(err);
        setLoading(false);
      }
    );

    return () => unsubscribe();
  }, [collectionName, documentId]);

  return { data, loading, error };
}

// Helper to remove undefined values (Firebase doesn't accept undefined)
function removeUndefined(obj: Record<string, any>): Record<string, any> {
  return Object.fromEntries(
    Object.entries(obj).filter(([_, value]) => value !== undefined)
  );
}

// Hook for mutations (create, update, delete)
// Auto-injects teamId on create for team-scoped collections
export function useMutation<T = DocumentData>(collectionName: string) {
  const { user } = useAuth();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  // createdAt, updatedAt, createdByUserId are auto-injected ΓÇö callers don't need to provide them
  const create = useCallback(async (data: Partial<Pick<T & Record<string, any>, 'createdAt' | 'updatedAt' | 'createdByUserId'>> & Omit<T, 'id' | 'createdAt' | 'updatedAt' | 'createdByUserId'>) => {
    setLoading(true);
    setError(null);
    try {
      const teamId = getGlobalTeamId();
      const autoTeamId = teamScopedCollections.has(collectionName) && teamId
        ? { teamId }
        : {};
      const docData = removeUndefined({
        ...autoTeamId,
        ...data,
        createdAt: Timestamp.now(),
        updatedAt: Timestamp.now(),
        createdByUserId: user?.uid || null
      });
      const docRef = await addDoc(collection(db, collectionName), docData);
      setLoading(false);
      return { id: docRef.id, ...docData };
    } catch (err) {
      setError(err as Error);
      setLoading(false);
      throw err;
    }
  }, [collectionName, user]);

  const update = useCallback(async (id: string, data: Partial<T>) => {
    setLoading(true);
    setError(null);
    try {
      const docRef = doc(db, collectionName, id);
      await updateDoc(docRef, removeUndefined({
        ...data,
        updatedAt: Timestamp.now()
      }) as any);
      setLoading(false);
    } catch (err) {
      setError(err as Error);
      setLoading(false);
      throw err;
    }
  }, [collectionName]);

  const remove = useCallback(async (id: string) => {
    setLoading(true);
    setError(null);
    try {
      const docRef = doc(db, collectionName, id);
      await deleteDoc(docRef);
      setLoading(false);
    } catch (err) {
      setError(err as Error);
      setLoading(false);
      throw err;
    }
  }, [collectionName]);

  return { create, update, remove, loading, error };
}

// Client-side pagination hook for any collection (works with team-scoped fetch-all strategy)
export function usePaginatedCollection<T = DocumentData>(
  collectionName: string,
  options?: QueryOptions & { pageSize?: number }
) {
  const { pageSize = 25, ...queryOptions } = options || {};
  const { data: allData, loading, error } = useCollection<T>(collectionName, queryOptions);
  const [page, setPage] = useState(0);

  // Reset page when data changes significantly (e.g., filter change)
  const totalItems = allData.length;
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));

  // Clamp page to valid range
  const safePage = Math.min(page, totalPages - 1);
  if (safePage !== page) setPage(safePage);

  const paginatedData = useMemo(() => {
    const start = safePage * pageSize;
    return allData.slice(start, start + pageSize);
  }, [allData, safePage, pageSize]);

  const nextPage = useCallback(() => {
    setPage(p => Math.min(p + 1, totalPages - 1));
  }, [totalPages]);

  const prevPage = useCallback(() => {
    setPage(p => Math.max(p - 1, 0));
  }, []);

  const goToPage = useCallback((target: number) => {
    setPage(Math.max(0, Math.min(target, totalPages - 1)));
  }, [totalPages]);

  return {
    data: paginatedData,
    allData,
    loading,
    error,
    page: safePage,
    totalPages,
    totalItems,
    pageSize,
    nextPage,
    prevPage,
    goToPage,
    hasNextPage: safePage < totalPages - 1,
    hasPrevPage: safePage > 0,
  };
}

import { useCollection, setGlobalTeamId } from './useFirestore';
import { useAuth } from '../contexts/AuthContext';
import { useMemo, useEffect, useRef } from 'react';
import { doc, updateDoc, Timestamp, collection, query, where, getDocs, writeBatch } from 'firebase/firestore';
import { db } from '../lib/firebase';

// Data scope determines what data a user can see
// 'all' = everything (admin/owner)
// 'team' = everything in their team (manager)
// 'assigned' = only data assigned to them (member)
// 'readonly' = same as assigned but no edits (viewer)
export type DataScope = 'all' | 'team' | 'assigned' | 'readonly';

export type UserPermissions = {
  canAccessProjects: boolean;
  canAccessTasks: boolean;
  canAccessCRM: boolean;
  canAccessInvoices: boolean;
  canAccessReports: boolean;
  canAccessSettings: boolean;
  canAccessGoals: boolean;
  canAccessTeams: boolean;
  canAccessChat: boolean;
  canAccessCustomers: boolean;
  canAccessServices: boolean;
  canAccessExpenses: boolean;
  canAccessProfile: boolean;
  canAccessTimeTracking: boolean;
  canEdit: boolean;
  canAssignTasks: boolean;
  canManageMembers: boolean;
  role: string | null;
  dataScope: DataScope;
  teamId: string | null;
  teamName: string | null;
  isAdmin: boolean;
  isOwner: boolean;
  isManager: boolean;
  isLoading: boolean;
};

// Full access for admin/owner
const fullAccessPermissions: Omit<UserPermissions, 'role' | 'dataScope' | 'teamId' | 'teamName' | 'isAdmin' | 'isOwner' | 'isManager' | 'isLoading'> = {
  canAccessProjects: true,
  canAccessTasks: true,
  canAccessCRM: true,
  canAccessInvoices: true,
  canAccessReports: true,
  canAccessSettings: true,
  canAccessGoals: true,
  canAccessTeams: true,
  canAccessChat: true,
  canAccessCustomers: true,
  canAccessServices: true,
  canAccessExpenses: true,
  canAccessProfile: true,
  canAccessTimeTracking: true,
  canEdit: true,
  canAssignTasks: true,
  canManageMembers: true,
};

// Minimal access for users not yet assigned to a team
const restrictedPermissions: Omit<UserPermissions, 'role' | 'dataScope' | 'teamId' | 'teamName' | 'isAdmin' | 'isOwner' | 'isManager' | 'isLoading'> = {
  canAccessProjects: false,
  canAccessTasks: false,
  canAccessCRM: false,
  canAccessInvoices: false,
  canAccessReports: false,
  canAccessSettings: false,
  canAccessGoals: false,
  canAccessTeams: false,
  canAccessChat: false,
  canAccessCustomers: false,
  canAccessServices: false,
  canAccessExpenses: false,
  canAccessProfile: true,
  canAccessTimeTracking: false,
  canEdit: false,
  canAssignTasks: false,
  canManageMembers: false,
};

export function usePermissions(): UserPermissions {
  const { user, loading: userLoading } = useAuth();
  
  // Query team members for this specific user (by uid or email) instead of ALL members
  const userIds = useMemo(() => {
    if (!user) return [];
    const ids = [user.uid];
    if (user.email) ids.push(user.email);
    return ids;
  }, [user]);

  // Primary query: by userId field (covers UID or email stored as userId)
  const { data: rawTeamMembers, loading: membersLoading, error: membersError } = useCollection<any>('teamMembers', {
    where: userIds.length > 0
      ? [{ field: 'userId', operator: 'in', value: userIds }]
      : [{ field: 'userId', operator: '==', value: '__never__' }],
    skipTeamFilter: true,
  });

  // Fallback query: by email field ΓÇö catches members added manually where userId wasn't set to the Firebase UID
  const { data: rawTeamMembersByEmail, loading: membersByEmailLoading, error: membersByEmailError } = useCollection<any>('teamMembers', {
    where: user?.email
      ? [{ field: 'email', operator: '==', value: user.email }]
      : [{ field: 'email', operator: '==', value: '__never__' }],
    skipTeamFilter: true,
  });

  // Merge both queries, deduplicate by id, prefer records already having the correct userId
  const teamMembers = useMemo(() => {
    const merged = new Map<string, any>();
    for (const m of rawTeamMembers || []) merged.set(m.id, m);
    for (const m of rawTeamMembersByEmail || []) if (!merged.has(m.id)) merged.set(m.id, m);
    return Array.from(merged.values()).filter((m: any) => m.status === 'Active');
  }, [rawTeamMembers, rawTeamMembersByEmail]);

  // Auto-link: when found by email but userId doesn't match current UID, update Firestore so future queries work
  const linkedRef = useRef<Set<string>>(new Set());
  useEffect(() => {
    if (!user) return;
    for (const m of rawTeamMembersByEmail || []) {
      if (m.userId !== user.uid && !linkedRef.current.has(m.id)) {
        linkedRef.current.add(m.id);
        updateDoc(doc(db, 'teamMembers', m.id), { userId: user.uid }).catch(console.error);
      }
    }
  }, [user, rawTeamMembersByEmail]);

  const { data: teams, loading: teamsLoading, error: teamsError } = useCollection<any>('teams', {
    skipTeamFilter: true,
  });

  // Check if the current user is the creator/owner of any team
  const isOwner = useMemo(() => {
    if (!user || !teams) return false;
    return teams.some((t: any) => t.createdByUserId === user.uid);
  }, [user, teams]);

  // Don't stay stuck loading forever if Firebase returns an error.
  // On error, isLoading becomes false but we still show restrictedPermissions (fail-safe).
  const isLoading = userLoading || ((membersLoading || membersByEmailLoading) && !membersError && !membersByEmailError) || (teamsLoading && !teamsError);
  const hasError = !!(membersError || membersByEmailError || teamsError);

  const permissions = useMemo((): UserPermissions => {
    // While loading or on error, return restricted permissions with loading flag (fail-safe)
    if (!user || isLoading || hasError) {
      return {
        ...restrictedPermissions,
        role: null,
        dataScope: 'assigned',
        teamId: null,
        teamName: null,
        isAdmin: false,
        isOwner: false,
        isManager: false,
        isLoading: isLoading,
      };
    }

    // OWNER: User who created a team gets full admin access
    if (isOwner) {
      // Check if owner also has a team membership (for teamId/teamName)
      const ownerMembership = teamMembers.length > 0 ? teamMembers[0] : null;
      let ownerTeamId = ownerMembership?.teamId || null;
      let ownerTeam = ownerTeamId ? teams?.find((t: any) => t.id === ownerTeamId) : null;

      // Fallback: if no teamMembers record, derive teamId from owned team directly
      if (!ownerTeamId && teams && teams.length > 0) {
        const ownedTeam = teams.find((t: any) => t.createdByUserId === user?.uid);
        if (ownedTeam) {
          ownerTeamId = ownedTeam.id;
          ownerTeam = ownedTeam;
        }
      }

      return {
        ...fullAccessPermissions,
        role: ownerMembership?.role || 'Admin',
        dataScope: 'all',
        teamId: ownerTeamId,
        teamName: ownerTeam?.name || null,
        isAdmin: true,
        isOwner: true,
        isManager: false,
        isLoading: false,
      };
    }

    // NO TEAM MEMBERSHIP and NOT OWNER: restricted access
    if (!teamMembers || teamMembers.length === 0) {
      return {
        ...restrictedPermissions,
        role: null,
        dataScope: 'assigned',
        teamId: null,
        teamName: null,
        isAdmin: false,
        isOwner: false,
        isManager: false,
        isLoading: false,
      };
    }

    // Has team membership ΓÇö use role-based permissions
    const membership = teamMembers[0];
    const team = teams?.find((t: any) => t.id === membership.teamId);
    const memberIsAdmin = membership.role === 'Admin';
    const memberIsManager = membership.role === 'Manager';

    // Admin role gets full access with 'all' data scope
    if (memberIsAdmin) {
      return {
        ...fullAccessPermissions,
        role: membership.role,
        dataScope: 'all',
        teamId: membership.teamId,
        teamName: team?.name || null,
        isAdmin: true,
        isOwner: false,
        isManager: false,
        isLoading: false,
      };
    }

    // Sales role: access to customers, CRM, invoices, services within team
    if (membership.role === 'Sales') {
      return {
        canAccessProjects: membership.canAccessProjects === true,
        canAccessTasks: membership.canAccessTasks === true,
        canAccessCRM: true,
        canAccessInvoices: membership.canAccessInvoices === true,
        canAccessReports: membership.canAccessReports === true,
        canAccessSettings: false,
        canAccessGoals: membership.canAccessGoals === true,
        canAccessTeams: false,
        canAccessChat: true,
        canAccessCustomers: true,
        canAccessServices: true,
        canAccessExpenses: membership.canAccessExpenses === true,
        canAccessProfile: true,
        canAccessTimeTracking: membership.canAccessTasks === true,
        canEdit: true,
        canAssignTasks: false,
        canManageMembers: false,
        role: membership.role,
        dataScope: 'team',
        teamId: membership.teamId,
        teamName: team?.name || null,
        isAdmin: false,
        isOwner: false,
        isManager: false,
        isLoading: false,
      };
    }

    // Manager role: full module access within team, can assign tasks/manage members
    if (memberIsManager) {
      return {
        canAccessProjects: true,
        canAccessTasks: true,
        canAccessCRM: membership.canAccessCRM === true,
        canAccessInvoices: membership.canAccessInvoices === true,
        canAccessReports: true,
        canAccessSettings: false,
        canAccessGoals: true,
        canAccessTeams: false,
        canAccessChat: true,
        canAccessCustomers: membership.canAccessCustomers === true || membership.canAccessCRM === true,
        canAccessServices: membership.canAccessServices === true || membership.canAccessInvoices === true,
        canAccessExpenses: membership.canAccessExpenses === true || membership.canAccessInvoices === true,
        canAccessProfile: true,
        canAccessTimeTracking: true,
        canEdit: true,
        canAssignTasks: true,
        canManageMembers: false,
        role: membership.role,
        dataScope: 'team',
        teamId: membership.teamId,
        teamName: team?.name || null,
        isAdmin: false,
        isOwner: false,
        isManager: true,
        isLoading: false,
      };
    }

    // Viewer role: read-only access to assigned items only
    // Member role: access to assigned items with edit rights
    const isViewer = membership.role === 'Viewer';
    
    return {
      canAccessProjects: membership.canAccessProjects === true,
      canAccessTasks: membership.canAccessTasks === true,
      canAccessCRM: membership.canAccessCRM === true,
      canAccessInvoices: membership.canAccessInvoices === true,
      canAccessReports: membership.canAccessReports === true,
      canAccessSettings: membership.canAccessSettings === true,
      canAccessGoals: membership.canAccessGoals === true || membership.canAccessTasks === true,
      canAccessTeams: false, // Only admin/owner can manage teams
      canAccessChat: true,
      canAccessCustomers: membership.canAccessCustomers === true || membership.canAccessCRM === true,
      canAccessServices: membership.canAccessServices === true || membership.canAccessInvoices === true,
      canAccessExpenses: membership.canAccessExpenses === true || membership.canAccessInvoices === true,
      canAccessProfile: true,
      canAccessTimeTracking: membership.canAccessTasks === true,
      canEdit: !isViewer, // Viewers can only read, Members can edit
      canAssignTasks: false, // Members can't assign to others
      canManageMembers: false,
      role: membership.role,
      dataScope: isViewer ? 'readonly' : 'assigned',
      teamId: membership.teamId,
      teamName: team?.name || null,
      isAdmin: false,
      isOwner: false,
      isManager: false,
      isLoading: false,
    };
  }, [user, teamMembers, teams, isOwner, isLoading]);

  // One-time normalization: if teamMember.userId is stored as email instead of UID,
  // update it and reassign any tasks/records that reference the old email-based userId.
  const normalizedRef = useRef(false);
  useEffect(() => {
    if (normalizedRef.current || !user || !user.email || !teamMembers || teamMembers.length === 0) return;

    const emailMember = teamMembers.find(
      (m: any) => m.userId === user.email && m.userId !== user.uid
    );
    if (!emailMember) return;

    normalizedRef.current = true;

    // Update the teamMember record to use the actual Firebase Auth UID
    (async () => {
      try {
        const memberRef = doc(db, 'teamMembers', emailMember.id);
        await updateDoc(memberRef, { userId: user.uid, updatedAt: Timestamp.now() });

        // Also update any tasks assigned to the old email-based userId
        const tasksSnap = await getDocs(
          query(collection(db, 'tasks'), where('assignedToUserId', '==', user.email))
        );
        if (!tasksSnap.empty) {
          const batch = writeBatch(db);
          tasksSnap.docs.forEach(d => {
            batch.update(d.ref, { assignedToUserId: user.uid, updatedAt: Timestamp.now() });
          });
          await batch.commit();
        }
      } catch {
        // Non-blocking ΓÇö RBAC filters already handle both uid and email
      }
    })();
  }, [user, teamMembers]);

  // Sync resolved teamId to global state via useEffect (safe, no side effects during render).
  // Guard 1: only fire when fully loaded.
  // Guard 2: only update with a non-null teamId ΓÇö a usePermissions instance that resolves
  //   with teamId=null (e.g. a non-member component that loaded before its data arrived)
  //   must NOT reset globalTeamId back to null and wipe out team-scoped collection data.
  useEffect(() => {
    if (!permissions.isLoading && permissions.teamId !== null) {
      setGlobalTeamId(permissions.teamId);
    }
  }, [permissions.isLoading, permissions.teamId]);

  return permissions;
}

import { useEffect, useRef } from 'react';
import { Capacitor } from '@capacitor/core';
import { PushNotifications } from '@capacitor/push-notifications';

/**
 * Registers for push notifications on native platforms (Android/iOS).
 * Returns the FCM token via the onToken callback.
 * No-ops gracefully on web.
 */
export function usePushNotifications(onToken?: (token: string) => void) {
  const onTokenRef = useRef(onToken);
  onTokenRef.current = onToken;

  useEffect(() => {
    if (!Capacitor.isNativePlatform()) return;

    let mounted = true;

    const register = async () => {
      const perm = await PushNotifications.requestPermissions();
      if (perm.receive !== 'granted') return;

      await PushNotifications.register();

      PushNotifications.addListener('registration', (token) => {
        if (mounted && onTokenRef.current) {
          onTokenRef.current(token.value);
        }
      });

      PushNotifications.addListener('registrationError', (err) => {
        console.error('Push registration failed:', err);
      });

      PushNotifications.addListener('pushNotificationReceived', (notification) => {
        console.log('Push received:', notification);
      });

      PushNotifications.addListener('pushNotificationActionPerformed', (action) => {
        console.log('Push action:', action);
      });
    };

    register();

    return () => {
      mounted = false;
      PushNotifications.removeAllListeners();
    };
  }, []);
}

import { useMemo } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { usePermissions, DataScope } from './usePermissions';
import type { Task, Project } from '../types';

// Helper: check if a value matches the current user's uid or email
// (teamMembers.userId can be stored as email instead of Firebase Auth UID)
function useUserIdentifiers(): string[] {
  const { user } = useAuth();
  return useMemo(() => {
    if (!user) return [];
    const ids = [user.uid];
    if (user.email) ids.push(user.email);
    return ids;
  }, [user]);
}

function matchesUser(value: string | null | undefined, identifiers: string[]): boolean {
  if (!value) return false;
  return identifiers.includes(value);
}

/**
 * Hook that filters tasks based on the user's data scope:
 * - 'all': Admin/Owner sees everything
 * - 'team': Manager sees all team tasks
 * - 'assigned'/'readonly': Member/Viewer sees only assigned tasks or tasks they created
 */
export function useFilteredTasks<T extends Partial<Task> & { id: string }>(
  tasks: T[] | undefined
): T[] {
  const { user } = useAuth();
  const { dataScope } = usePermissions();
  const userIds = useUserIdentifiers();

  return useMemo(() => {
    if (!tasks) return [];
    if (!user) return [];

    // Admin/Owner: see everything
    if (dataScope === 'all') return tasks;

    // Manager: see all team tasks (already filtered by teamId via useCollection)
    if (dataScope === 'team') return tasks;

    // Member/Viewer: see only tasks assigned to them, created by them, or where they're collaborators
    return tasks.filter(t => {
      if (matchesUser(t.assignedToUserId, userIds)) return true;
      if (matchesUser(t.createdByUserId, userIds)) return true;
      // Check collaboratorIds
      if (t.collaboratorIds) {
        const ids: string[] = Array.isArray(t.collaboratorIds)
          ? t.collaboratorIds
          : [];
        if (ids.some(id => userIds.includes(id))) return true;
      }
      return false;
    });
  }, [tasks, user, userIds, dataScope]);
}

/**
 * Hook that filters projects based on the user's data scope:
 * - 'all': Admin/Owner sees everything
 * - 'team': Manager sees all team projects
 * - 'assigned'/'readonly': Member/Viewer sees only projects where they have assigned tasks
 */
export function useFilteredProjects<T extends Partial<Project> & { id: string }>(
  projects: T[] | undefined,
  tasks?: (Partial<Task> & { id: string })[]
): T[] {
  const { user } = useAuth();
  const { dataScope } = usePermissions();
  const userIds = useUserIdentifiers();

  return useMemo(() => {
    if (!projects) return [];
    if (!user) return [];

    if (dataScope === 'all' || dataScope === 'team') return projects;

    // Member/Viewer: see projects they created, are a member of, or have tasks in
    const myProjectIds = new Set<string>();

    // Projects they created
    projects.forEach(p => {
      if (matchesUser(p.createdByUserId, userIds)) myProjectIds.add(p.id);
    });

    // Projects where they are explicitly listed as a member
    projects.forEach(p => {
      if (Array.isArray(p.memberUserIds) && p.memberUserIds.some(id => userIds.includes(id))) {
        myProjectIds.add(p.id);
      }
    });

    // Projects where they have assigned tasks
    if (tasks) {
      tasks.forEach(t => {
        if (!t.projectId) return;
        if (matchesUser(t.assignedToUserId, userIds) || matchesUser(t.createdByUserId, userIds)) {
          myProjectIds.add(t.projectId);
        }
        if (t.collaboratorIds) {
          const ids: string[] = Array.isArray(t.collaboratorIds)
            ? t.collaboratorIds
            : [];
          if (ids.some(id => userIds.includes(id))) {
            myProjectIds.add(t.projectId!);
          }
        }
      });
    }

    return projects.filter(p => myProjectIds.has(p.id));
  }, [projects, tasks, user, userIds, dataScope]);
}

/**
 * Generic filter for records that have a createdByUserId.
 * - 'all'/'team': see everything
 * - 'assigned'/'readonly': see only own records
 */
export function useFilteredByOwner<T extends { id: string; createdByUserId?: string | null }>(
  data: T[] | undefined
): T[] {
  const { user } = useAuth();
  const { dataScope } = usePermissions();
  const userIds = useUserIdentifiers();

  return useMemo(() => {
    if (!data) return [];
    if (!user) return [];
    if (dataScope === 'all' || dataScope === 'team') return data;
    return data.filter(d => matchesUser(d.createdByUserId, userIds));
  }, [data, user, userIds, dataScope]);
}

/**
 * Filter time entries: member/viewer sees only their own entries
 */
export function useFilteredTimeEntries<T extends { id: string; userId?: string }>(
  entries: T[] | undefined
): T[] {
  const { user } = useAuth();
  const { dataScope } = usePermissions();
  const userIds = useUserIdentifiers();

  return useMemo(() => {
    if (!entries) return [];
    if (!user) return [];
    if (dataScope === 'all' || dataScope === 'team') return entries;
    return entries.filter(e => matchesUser(e.userId, userIds));
  }, [entries, user, userIds, dataScope]);
}

/**
 * Utility: check if current user can see all data
 */
export function useScopeIsAll(): boolean {
  const { dataScope } = usePermissions();
  return dataScope === 'all' || dataScope === 'team';
}

import { useEffect, useRef } from 'react';
import { collection, getDocs, writeBatch, doc } from 'firebase/firestore';
import { db } from '../lib/firebase';
import { useAuth } from '../contexts/AuthContext';
import { usePermissions } from './usePermissions';

/**
 * One-time migration: stamps teamId on existing Firestore documents
 * that were created before data-isolation (Phase 47).
 * Runs once per user, tracked via localStorage.
 */

const TEAM_SCOPED_COLLECTIONS = [
  'tasks', 'invoices', 'customers', 'leads', 'services',
  'expenses', 'goals', 'timeEntries', 'channels', 'messages',
  'activities', 'clientRequests', 'invoiceItems', 'taskComments',
  'taskCollaborators', 'customIndustries', 'typingIndicators',
  'directMessages', 'milestones', 'serviceInquiries', 'projectComments',
  'workspaceFolders', 'workspaceDriveFiles', 'projects',
];

export function useTeamDataMigration() {
  const { user } = useAuth();
  const { teamId, isLoading } = usePermissions();
  const migrating = useRef(false);

  useEffect(() => {
    if (!user || !teamId || isLoading || migrating.current) return;

    const migrationKey = `teamId_migration_v2_${user.uid}`;
    if (localStorage.getItem(migrationKey)) return;

    migrating.current = true;

    const migrate = async () => {
      try {
        let totalUpdated = 0;

        for (const colName of TEAM_SCOPED_COLLECTIONS) {
          const snapshot = await getDocs(collection(db, colName));
          const docsWithoutTeamId = snapshot.docs.filter(
            d => !d.data().teamId
          );

          if (docsWithoutTeamId.length === 0) continue;

          // Firestore writeBatch limit is 500 operations
          for (let i = 0; i < docsWithoutTeamId.length; i += 500) {
            const batch = writeBatch(db);
            const chunk = docsWithoutTeamId.slice(i, i + 500);
            chunk.forEach(docSnap => {
              batch.update(doc(db, colName, docSnap.id), { teamId });
            });
            await batch.commit();
            totalUpdated += chunk.length;
          }
        }

        localStorage.setItem(migrationKey, Date.now().toString());
        if (totalUpdated > 0) {
          console.log(`[Migration] Stamped teamId on ${totalUpdated} documents`);
        }
      } catch (err) {
        console.error('[Migration] Failed to stamp teamId:', err);
      } finally {
        migrating.current = false;
      }
    };

    migrate();
  }, [user, teamId, isLoading]);
}

