                    placeholder={`Shkruaj${chatMode === 'channel' ? ` n├½ #${CHANNELS.find(c => c.id === activeChannel)?.name || activeChannel}` : ` te ${getUserDisplayName(activeDirectUserId || '')}`}...`}
                    disabled={isSending}
                    rows={1}
                    className="flex-1 min-w-0 bg-transparent border-0 outline-none text-sm resize-none py-1.5 placeholder:text-muted-foreground/40 max-h-[120px]"
                  />

                  <Button
                    type="submit"
                    size="icon"
                    className={`h-8 w-8 rounded-xl flex-shrink-0 mb-0.5 transition-all ${
                      messageText.trim() || attachmentUrl.trim() ? 'bg-primary text-primary-foreground shadow-sm hover:bg-primary/90' : 'bg-transparent text-muted-foreground/30'
                    }`}
                    disabled={isSending || (!messageText.trim() && !attachmentUrl.trim()) || (chatMode === 'direct' && !activeDirectUserId)}
                  >
                    <Send className="h-4 w-4" />
                  </Button>
                </div>
              </form>
              <div className="flex items-center justify-between mt-1.5 px-1">
                <p className="text-[10px] text-muted-foreground/30">Enter d├½rgon ┬╖ Shift+Enter rresht i ri</p>
                <button className="text-[10px] text-muted-foreground/30 hover:text-primary transition-colors flex items-center gap-1">
                  <Link2 className="h-2.5 w-2.5" /> Lidh me task
                </button>
              </div>
              {messageMutation.error && <p className="text-xs text-destructive mt-1">{messageMutation.error.message}</p>}
            </div>
          </>
        )}
      </main>
    </div>
  );
};

