          onChange={(e) => setTax(parseFloat(e.target.value) || 0)}
        />
      </div>

      <div>
        <Label htmlFor="paymentUrl">URL e Pages├½s Online</Label>
        <Input
          id="paymentUrl"
          name="paymentUrl"
          type="url"
          placeholder="https://payment.example.com/invoice/..."
          value={paymentUrl}
          onChange={(e) => setPaymentUrl(e.target.value)}
        />
      </div>

      <div>
        <Label htmlFor="notes">Sh├½nime</Label>
        <Textarea id="notes" name="notes" rows={3} placeholder="Sh├½nime shtes├½..." value={notes} onChange={(e) => setNotes(e.target.value)} />
      </div>

      <div className="border-t pt-4">
        <div className="space-y-2 text-right">
          <div className="flex justify-between">
            <span className="text-muted-foreground">N├½ntotali:</span>
            <span className="font-medium">{calculateSubtotal().toFixed(2)} L</span>
          </div>
          <div className="flex justify-between">
            <span className="text-muted-foreground">Taksa:</span>
            <span className="font-medium">{tax.toFixed(2)} L</span>
          </div>
          <div className="flex justify-between text-lg font-bold">
            <span>Total:</span>
            <span>{(calculateSubtotal() + tax).toFixed(2)} L</span>
          </div>
        </div>
      </div>

      <Button type="submit" className="w-full">
        {isEditing ? 'Ruaj Ndryshimet' : 'Krijo Fatur├½n'}
      </Button>
    </form>
  );
};

