// Calendar View
const ProjectCalendarView: React.FC<{
  tasks: Task[];
  onTaskClick: (task: Task) => void;
}> = ({ tasks, onTaskClick }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const daysInMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate();
  const firstDay = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1).getDay();

  const days = [];
  for (let i = 0; i < firstDay; i++) {
    days.push(<div key={`empty-${i}`} className="min-h-[80px] bg-muted/20" />);
  }

  for (let day = 1; day <= daysInMonth; day++) {
    const date = new Date(currentDate.getFullYear(), currentDate.getMonth(), day);
    const dayTasks = tasks.filter(task => {
      const taskDate = new Date(task.endDate);
      return taskDate.toDateString() === date.toDateString();
    });

    days.push(
      <div key={day} className="min-h-[80px] border border-border p-1 bg-background">
        <div className="font-medium text-xs mb-1 text-muted-foreground">{day}</div>
        <div className="space-y-1">
          {dayTasks.slice(0, 2).map(task => (
            <div
              key={task.id}
              className="text-xs p-1 bg-primary/10 rounded cursor-pointer hover:bg-primary/20 truncate"
              onClick={() => onTaskClick(task)}
            >
              {task.title}
            </div>
          ))}
          {dayTasks.length > 2 && (
            <div className="text-xs text-muted-foreground">+{dayTasks.length - 2} m├½ shum├½</div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 space-y-4">
      <div className="flex items-center justify-between">
        <Button variant="outline" size="sm" onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1))}>
          Para
        </Button>
        <h2 className="text-sm font-medium">
          {currentDate.toLocaleDateString('sq-AL', { month: 'long', year: 'numeric' })}
        </h2>
        <Button variant="outline" size="sm" onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1))}>
          Pas
        </Button>
      </div>
      <div className="grid grid-cols-7 gap-px bg-border">
        {['Diel', 'H├½n', 'Mar', 'M├½r', 'Enj', 'Pre', 'Sht'].map(day => (
          <div key={day} className="bg-muted p-1 text-center text-xs font-medium">{day}</div>
        ))}
        {days}
      </div>
    </div>
  );
};

// --- @dnd-kit helper components ---
function ProjectKanbanColumn({ id, children }: { id: string; children: React.ReactNode }) {
  const { setNodeRef, isOver } = useDroppable({ id });
  return (
    <div ref={setNodeRef} className={`flex flex-col min-w-[250px] transition-colors rounded-lg p-1 ${isOver ? 'bg-primary/5 ring-1 ring-primary/30' : ''}`}>
      {children}
    </div>
  );
}

function ProjectSortableCard({ id, children }: { id: string; children: React.ReactNode }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id });
  const style = { transform: CSS.Transform.toString(transform), transition, opacity: isDragging ? 0.4 : 1 };
  return (
    <div ref={setNodeRef} style={style} {...attributes} {...listeners}>
      {children}
    </div>
  );
}

export default ProjectDetailView;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCollection, useMutation } from '../hooks/useFirestore';
import { useAuth } from '../contexts/AuthContext';
import { usePermissions } from '../contexts/PermissionsContext';
import { Search, Plus, List, Users, ChevronDown, MoreVertical, Folder, Trash2 } from 'lucide-react';
import { Card } from '../components/ui/card';
import { Button } from '../components/ui/button';
import { Badge } from '../components/ui/badge';
import { Input } from '../components/ui/input';
import { Label } from '../components/ui/label';
import { Textarea } from '../components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '../components/ui/dialog';
import { Popover, PopoverContent, PopoverTrigger } from '../components/ui/popover';
import { Checkbox } from '../components/ui/checkbox';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '../components/ui/dropdown-menu';
import { useActivityLogger } from '../hooks/useActivityLogger';
import { useFilteredProjects } from '../hooks/useRoleFilteredData';
import { useUserNames } from '../hooks/useUserNames';
import type { Project, Task, Team, TeamMember, Customer, Invoice, Service, InvoiceItem } from '../types';

const ProjectsView: React.FC = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const permissions = usePermissions();
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [projectToDelete, setProjectToDelete] = useState<{ id: string; name: string } | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  
  // Filters
  const [filterOwner, setFilterOwner] = useState<string>('all');
  const [filterTeam, setFilterTeam] = useState<string>('all');
  const [filterStatus, setFilterStatus] = useState<string>('all');
  const [filterMembers, setFilterMembers] = useState<string[]>([]);

  // Firebase hooks
  const { data: rawProjects, loading: projectsLoading } = useCollection<Project>('projects', {
    orderBy: { field: 'updatedAt', direction: 'desc' },
    skipTeamFilter: true,
  });
  const { data: allTasks } = useCollection<Task>('tasks');
  // Role-based filtering: Member/Viewer see only projects they're involved in
  const projects = useFilteredProjects(rawProjects, allTasks);
  const { data: teams } = useCollection<Team>('teams');
  const { data: teamMembers } = useCollection<TeamMember>('teamMembers', {
    where: [{ field: 'status', operator: '==', value: 'Active' }]
  });
  const { data: customers } = useCollection<Customer>('customers', { skipTeamFilter: true });
  const { data: services } = useCollection<Service>('services', { skipTeamFilter: true });
  
  const projectMutation = useMutation<Project>('projects');
  const taskMutation = useMutation<Task>('tasks');
  const invoiceMutation = useMutation<Invoice>('invoices');
  const invoiceItemMutation = useMutation<InvoiceItem>('invoiceItems');
  const logActivity = useActivityLogger();

  const { getName, getInitials } = useUserNames(teamMembers || []);

  // Get unique owners from projects
  const owners = React.useMemo(() => {
    if (!projects) return [];
    const ownerIds = [...new Set(projects.map(p => p.createdByUserId).filter(Boolean))];
    return ownerIds;
  }, [projects]);

  // Filter projects
  const filteredProjects = React.useMemo(() => {
    if (!projects) return [];
    
    let filtered = [...projects];
    
    // Search filter
    if (searchQuery) {
      filtered = filtered.filter(p => 
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.description?.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }
    
    // Owner filter
    if (filterOwner !== 'all') {
      filtered = filtered.filter(p => p.createdByUserId === filterOwner);
    }
    
    // Team filter
    if (filterTeam !== 'all') {
      filtered = filtered.filter(p => p.teamId === filterTeam);
    }
    
    // Status filter
    if (filterStatus !== 'all') {
      filtered = filtered.filter(p => p.status === filterStatus);
    }

    // Members filter ΓÇö checks memberUserIds first, falls back to team membership
    if (filterMembers.length > 0 && teamMembers) {
      filtered = filtered.filter(p => {
        const explicit = (p.memberUserIds as string[] | undefined);
        if (explicit && explicit.length > 0) {
          return filterMembers.some(id => explicit.includes(id));
        }
        // fallback: any member of the project's team
        if (!p.teamId) return false;
        const projectTeamMembers = teamMembers.filter(m => m.teamId === p.teamId);
        return filterMembers.some(memberId => projectTeamMembers.some(m => m.userId === memberId));
      });
    }
    
    return filtered;
  }, [projects, searchQuery, filterOwner, filterTeam, filterStatus, filterMembers, teamMembers]);

  // Get members for a project:
  //  - if memberUserIds is set ΓåÆ show exactly those people
  //  - otherwise fall back to everyone on the project's team
  const getProjectMembers = (project: Project) => {
    if (!teamMembers) return [];
    const explicit = (project.memberUserIds as string[] | undefined);
    if (explicit && explicit.length > 0) {
      return teamMembers.filter(m => explicit.includes(m.userId));
    }
    if (!project.teamId) return [];
    return teamMembers.filter(m => m.teamId === project.teamId);
  };

  // Get team name
  const getTeamName = (teamId?: string) => {
    if (!teamId || !teams) return null;
    return teams.find(t => t.id === teamId);
  };

  // Format relative time
  const formatRelativeTime = (date: Date) => {
    if (!date) return 'Pa koh├½';
    const now = new Date();
    const dateObj = new Date(date);
    if (isNaN(dateObj.getTime())) return 'Pa koh├½';
    const diff = now.getTime() - dateObj.getTime();
    if (diff < 0) return 'n├½ t├½ ardhmen';
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    const hours = Math.floor(diff / (1000 * 60 * 60));
    const minutes = Math.floor(diff / (1000 * 60));
    
    if (minutes < 60) return `${minutes} min m├½ par├½`;
    if (hours < 24) return `${hours} or├½ m├½ par├½`;
    if (days === 1) return 'Dje';
    if (days < 7) return `${days} dit├½ m├½ par├½`;
    return new Date(date).toLocaleDateString('sq-AL');
  };

  const handleCreateProject = async (formData: FormData) => {
    const name = formData.get('name') as string;
    const description = formData.get('description') as string;
    const status = formData.get('status') as string;
    const teamId = formData.get('teamId') as string;
    const budgetStr = formData.get('budget') as string;
    const custId = formData.get('customerId') as string;
    const responsibleUserId = formData.get('responsibleUserId') as string;
    const isRecurring = formData.get('isRecurring') === 'true';
    const recurringFrequency = formData.get('recurringFrequency') as string;
    const memberUserIdsStr = formData.get('memberUserIds') as string;
    let memberUserIds: string[] | undefined;
    if (memberUserIdsStr) {
      try { memberUserIds = JSON.parse(memberUserIdsStr); } catch { memberUserIds = undefined; }
    }
    const selectedServiceIdsStr = formData.get('selectedServiceIds') as string;
    let selectedServiceIds: string[] | undefined;
    if (selectedServiceIdsStr) {
      try { selectedServiceIds = JSON.parse(selectedServiceIdsStr); } catch { selectedServiceIds = undefined; }
    }

    const budgetRaw = budgetStr ? parseFloat(budgetStr) : undefined;
    const budget = budgetRaw !== undefined && !isNaN(budgetRaw) ? budgetRaw : undefined;
    const resolvedCustomerId = custId && custId !== '__none__' ? custId : undefined;
    const resolvedTeamId = teamId && teamId !== '__none__' ? teamId : undefined;

    const newProject = await projectMutation.create({
      name,
      description,
      status,
      teamId: resolvedTeamId,
      budget,
      spent: 0,
      customerId: resolvedCustomerId,
      responsibleUserId: responsibleUserId && responsibleUserId !== '__none__' ? responsibleUserId : undefined,
      isRecurring: isRecurring || undefined,
      recurringFrequency: isRecurring && recurringFrequency ? recurringFrequency as any : undefined,
      memberUserIds: memberUserIds && memberUserIds.length > 0 ? memberUserIds : undefined,
      serviceIds: selectedServiceIds && selectedServiceIds.length > 0 ? selectedServiceIds : undefined,
    });

    // Always create a Draft invoice when a project is created
    const now = new Date();
    const dueDate = new Date(now.getFullYear(), now.getMonth() + 1, 0); // last day of month

    if (isRecurring) {
      const invoiceLabel = `AUTO-${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${newProject.id.slice(0, 6).toUpperCase()}`;
      const newInvoice = await invoiceMutation.create({
        invoiceNumber: invoiceLabel,
        projectId: newProject.id,
        customerId: resolvedCustomerId,
        teamId: resolvedTeamId,
        amount: budget || 0,
        subtotal: budget || 0,
        total: budget || 0,
        tax: 0,
        status: 'Draft',
        notes: `Fatur├½ e gjeneruar automatikisht p├½r projektin periodik "${name}".`,
        dueDate,
        isRecurring: true,
        recurringFrequency: (recurringFrequency || 'monthly') as any,
        autoGenerated: true,
        emailSent: false,
        reminderSent: false,
        reminder25Sent: false,
        reminderLastDaySent: false,
      } as any);

      // Create invoiceItems for selected services
      if (selectedServiceIds && selectedServiceIds.length > 0 && services) {
        for (const serviceId of selectedServiceIds) {
          const service = services.find(s => s.id === serviceId);
          if (service) {
            await invoiceItemMutation.create({
              invoiceId: (newInvoice as any).id,
              serviceId: service.id,
              quantity: 1,
              unitPrice: service.price || 0,
              totalPrice: service.price || 0,
            } as any);
          }
        }
      }

      // Send invoice email to customer via API (sets status ΓåÆ Pending)
      if (resolvedCustomerId) {
        try {
          const authToken = await user?.getIdToken();
          await fetch('/api/send-invoice-email', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              ...(authToken ? { Authorization: `Bearer ${authToken}` } : {}),
            },
            body: JSON.stringify({ invoiceId: (newInvoice as any).id }),
          });
        } catch {
          // email failure is non-blocking
        }
      }
    } else {
      // Non-recurring project: create a plain Draft invoice
      const invoiceLabel = `DRAFT-${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${newProject.id.slice(0, 6).toUpperCase()}`;
      const newInvoice = await invoiceMutation.create({
        invoiceNumber: invoiceLabel,
        projectId: newProject.id,
        customerId: resolvedCustomerId,
        teamId: resolvedTeamId,
        amount: budget || 0,
        subtotal: budget || 0,
        total: budget || 0,
        tax: 0,
        status: 'Draft',
        notes: `Fatur├½ draft e krijuar automatikisht p├½r projektin "${name}".`,
        dueDate,
      } as any);

      // Create invoiceItems for selected services
      if (selectedServiceIds && selectedServiceIds.length > 0 && services) {
        for (const serviceId of selectedServiceIds) {
          const service = services.find(s => s.id === serviceId);
          if (service) {
            await invoiceItemMutation.create({
              invoiceId: (newInvoice as any).id,
              serviceId: service.id,
              quantity: 1,
              unitPrice: service.price || 0,
              totalPrice: service.price || 0,
            } as any);
          }
        }
      }
    }

    logActivity('project_created', `Projekt i ri: ${name}`, { entityType: 'project', entityId: newProject.id });
    setIsCreateDialogOpen(false);
    navigate(`/app/projects/${newProject.id}`);
  };

  const handleDeleteProject = async (id: string, name: string) => {
    const projectTasks = allTasks?.filter(t => (t as any).projectId === id) || [];
    await Promise.all(projectTasks.map(t => taskMutation.remove(t.id)));
    await projectMutation.remove(id);
    logActivity('project_deleted', `Projekt i fshi├½r: ${name}`, { entityType: 'project', entityId: id });
    setProjectToDelete(null);
  };

  if (projectsLoading) {
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div className="h-8 w-48 skeleton rounded" />
          <div className="h-10 w-32 skeleton rounded" />
        </div>
        <div className="h-10 w-full skeleton rounded" />
        <div className="space-y-2">
          {[1, 2, 3, 4, 5].map((i) => (
            <div key={i} className="h-16 w-full skeleton rounded" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <h1 className="text-xl sm:text-2xl font-semibold text-foreground">Shfleto projektet</h1>
        {permissions.canEdit && (
          <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
            <DialogTrigger asChild>
              <Button className="bg-primary text-primary-foreground w-full sm:w-auto">
                <Plus className="w-4 h-4 mr-2" />
                Krijo projekt
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Krijo Projekt t├½ Ri</DialogTitle>
              </DialogHeader>
              <ProjectForm onSubmit={handleCreateProject} teams={teams || []} customers={customers || []} teamMembers={teamMembers || []} services={services || []} />
            </DialogContent>
          </Dialog>
        )}
      </div>

      {/* Search Bar */}
      <div className="relative">
        <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
        <Input
          placeholder="Gjej nj├½ projekt"
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="pl-10 h-10"
        />
      </div>

      {/* Filters */}
      <div className="flex items-center gap-2 flex-wrap">
        {/* Owner Filter */}
        <Popover>
          <PopoverTrigger asChild>
            <Button variant="outline" size="sm" className="h-8">
              Pronari
              <ChevronDown className="w-3 h-3 ml-1" />
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-48 p-2" align="start">
            <div className="space-y-1">
              <button
                className={`w-full text-left px-2 py-1.5 text-sm rounded hover:bg-muted ${filterOwner === 'all' ? 'bg-muted' : ''}`}
                onClick={() => setFilterOwner('all')}
              >
                T├½ gjith├½
              </button>
              {user && (
                <button
                  className={`w-full text-left px-2 py-1.5 text-sm rounded hover:bg-muted ${filterOwner === user.uid ? 'bg-muted' : ''}`}
                  onClick={() => setFilterOwner(user.uid)}
                >
                  Un├½
                </button>
              )}
            </div>
          </PopoverContent>
        </Popover>

        {/* Members Filter */}
        <Popover>
          <PopoverTrigger asChild>
            <Button variant="outline" size="sm" className="h-8">
              An├½tar├½t
              <ChevronDown className="w-3 h-3 ml-1" />
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-56 p-2" align="start">
            <div className="space-y-1">
              <p className="text-xs text-muted-foreground px-2 py-1">Filtro sipas an├½tar├½ve</p>
              {teamMembers?.slice(0, 30).map(member => (
                <div key={member.id} className="flex items-center gap-2 px-2 py-1.5">
                  <Checkbox
                    checked={filterMembers.includes(member.userId)}
                    onCheckedChange={(checked) => {
                      if (checked) {
                        setFilterMembers([...filterMembers, member.userId]);
                      } else {
                        setFilterMembers(filterMembers.filter(id => id !== member.userId));
                      }
                    }}
                  />
                  <div className="w-6 h-6 rounded-full bg-primary/20 flex items-center justify-center text-xs">
                    {getInitials(member.userId)}
                  </div>
                  <span className="text-sm truncate">{getName(member.userId)}</span>
                </div>
              ))}
            </div>
          </PopoverContent>
        </Popover>

        {/* Teams Filter */}
        <Popover>
          <PopoverTrigger asChild>
            <Button variant="outline" size="sm" className="h-8">
              Ekipet
              <ChevronDown className="w-3 h-3 ml-1" />
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-48 p-2" align="start">
            <div className="space-y-1">
              <button
                className={`w-full text-left px-2 py-1.5 text-sm rounded hover:bg-muted ${filterTeam === 'all' ? 'bg-muted' : ''}`}
                onClick={() => setFilterTeam('all')}
              >
                T├½ gjitha
              </button>
              {teams?.map(team => (
                <button
                  key={team.id}
                  className={`w-full text-left px-2 py-1.5 text-sm rounded hover:bg-muted ${filterTeam === team.id ? 'bg-muted' : ''}`}
                  onClick={() => setFilterTeam(team.id)}
                >
                  {team.name}
                </button>
              ))}
            </div>
          </PopoverContent>
        </Popover>

        {/* Status Filter */}
        <Popover>
          <PopoverTrigger asChild>
            <Button variant="outline" size="sm" className="h-8">
              Statusi
              <ChevronDown className="w-3 h-3 ml-1" />
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-40 p-2" align="start">
            <div className="space-y-1">
              <button
                className={`w-full text-left px-2 py-1.5 text-sm rounded hover:bg-muted ${filterStatus === 'all' ? 'bg-muted' : ''}`}
                onClick={() => setFilterStatus('all')}
              >
                T├½ gjitha
              </button>
              {['Active', 'Planning', 'In Review', 'On Hold', 'Completed', 'Archived', 'Cancelled'].map(status => (
                <button
                  key={status}
                  className={`w-full text-left px-2 py-1.5 text-sm rounded hover:bg-muted ${filterStatus === status ? 'bg-muted' : ''}`}
                  onClick={() => setFilterStatus(status)}
                >
                  {status}
                </button>
              ))}
            </div>
          </PopoverContent>
        </Popover>

        {/* Clear Filters */}
        {(filterOwner !== 'all' || filterTeam !== 'all' || filterStatus !== 'all' || filterMembers.length > 0) && (
          <Button 
            variant="ghost" 
            size="sm" 
            className="h-8 text-muted-foreground"
            onClick={() => {
              setFilterOwner('all');
              setFilterTeam('all');
              setFilterStatus('all');
              setFilterMembers([]);
            }}
          >
            Pastro filtrat
          </Button>
        )}
      </div>

      {/* Projects Table */}
      <div className="border rounded-lg overflow-hidden">
        {/* Table Header */}
        <div className="grid grid-cols-12 gap-4 px-4 py-3 bg-muted/50 border-b text-sm font-medium text-muted-foreground">
          <div className="col-span-5">Emri</div>
          <div className="col-span-2">An├½tar├½t</div>
          <div className="col-span-3">Ekipet dhe portfoliot</div>
          <div className="col-span-2 text-right">Modifikuar</div>
        </div>

        {/* Table Body */}
        <div className="divide-y">
          {filteredProjects.map((project) => {
            const members = getProjectMembers(project);
            const team = getTeamName(project.teamId);
            const isJoined = members.some(m => m.userId === user?.uid);
            
            return (
              <div
                key={project.id}
                className="grid grid-cols-12 gap-4 px-4 py-3 hover:bg-muted/30 cursor-pointer transition-colors items-center group"
                onClick={() => navigate(`/app/projects/${project.id}`)}
              >
                {/* Name Column */}
                <div className="col-span-5 flex items-center gap-3">
                  <div className="w-8 h-8 rounded bg-pink-100 flex items-center justify-center flex-shrink-0">
                    <List className="w-4 h-4 text-pink-600" />
                  </div>
                  <div className="min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="font-medium text-foreground truncate">{project.name}</span>
                    </div>
                    {isJoined && (
                      <span className="text-xs text-success">Joined</span>
                    )}
                  </div>
                </div>

                {/* Members Column */}
                <div className="col-span-2">
                  <div className="flex items-center">
                    <div className="flex -space-x-2">
                      {members.slice(0, 3).map((member, idx) => (
                        <div
                          key={member.id}
                          className="w-7 h-7 rounded-full bg-primary/20 border-2 border-background flex items-center justify-center text-xs font-medium"
                          title={getName(member.userId)}
                        >
                          {getInitials(member.userId)}
                        </div>
                      ))}
                    </div>
                    {members.length > 3 && (
                      <span className="ml-1 text-xs text-muted-foreground">
                        ...
                      </span>
                    )}
                    {members.length === 0 && (
                      <span className="text-xs text-muted-foreground">ΓÇö</span>
                    )}
                  </div>
                </div>

                {/* Teams Column */}
                <div className="col-span-3">
                  {team ? (
                    <div className="flex items-center gap-2">
                      <Users className="w-4 h-4 text-muted-foreground" />
                      <Badge variant="secondary" className="text-xs font-normal">
                        {team.name}
                      </Badge>
                    </div>
                  ) : (
                    <span className="text-xs text-muted-foreground">ΓÇö</span>
                  )}
                </div>

                {/* Last Modified Column */}
                <div className="col-span-2 text-right flex items-center justify-end gap-1">
                  <span className="text-sm text-muted-foreground">
                    {formatRelativeTime(project.updatedAt)}
                  </span>
                  {permissions.canEdit && (
                    <Button
                      variant="ghost"
                      size="sm"
                      className="text-destructive hover:text-destructive h-7 w-7 p-0 opacity-0 group-hover:opacity-100 transition-opacity"
                      onClick={(e) => { e.stopPropagation(); setProjectToDelete({ id: project.id, name: project.name }); }}
                      title="Fshi projektin"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </Button>
                  )}
                </div>
              </div>
            );
          })}

          {filteredProjects.length === 0 && (
            <div className="text-center py-12 text-muted-foreground">
              <Folder className="w-12 h-12 mx-auto mb-4 opacity-50" />
              <p>Asnj├½ projekt u gjet</p>
              {searchQuery && (
                <Button 
                  variant="link" 
                  className="mt-2"
                  onClick={() => setSearchQuery('')}
                >
                  Pastro k├½rkimin
                </Button>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Results Count */}
      <div className="text-sm text-muted-foreground">
        {filteredProjects.length} projekt{filteredProjects.length !== 1 ? 'e' : ''}
      </div>

      {/* Delete Project Confirmation */}
      <Dialog open={!!projectToDelete} onOpenChange={(open) => { if (!open) setProjectToDelete(null); }}>
        <DialogContent className="max-w-sm">
          <DialogHeader><DialogTitle>Fshi Projektin</DialogTitle></DialogHeader>
          <p className="text-sm text-muted-foreground">Je i sigurt q├½ d├½shiron t├½ fshish projektin <span className="font-semibold">"{projectToDelete?.name}"</span>? T├½ gjitha detyrat e lidhura do t├½ fshihen gjithashtu.</p>
          <div className="flex justify-end gap-2 pt-2">
            <Button variant="outline" onClick={() => setProjectToDelete(null)}>Anulo</Button>
            <Button variant="destructive" onClick={() => projectToDelete && handleDeleteProject(projectToDelete.id, projectToDelete.name)}>Fshi</Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

// Project Form Component
const ProjectForm: React.FC<{
  onSubmit: (data: FormData) => void;
  teams: Team[];
  customers?: Customer[];
  teamMembers?: import('../types').TeamMember[];
  services?: Service[];
  initialData?: Project;
}> = ({ onSubmit, teams, customers, teamMembers, services, initialData }) => {
  const [teamId, setTeamId] = useState(initialData?.teamId || '__none__');
  const [custId, setCustId] = useState((initialData as any)?.customerId || '__none__');
  const [responsibleUserId, setResponsibleUserId] = useState(initialData?.responsibleUserId || '__none__');
  const [isRecurring, setIsRecurring] = useState(initialData?.isRecurring || false);
  const [recurringFrequency, setRecurringFrequency] = useState(initialData?.recurringFrequency || 'monthly');
  const [memberUserIds, setMemberUserIds] = useState<string[]>(initialData?.memberUserIds || []);
  const [selectedServiceIds, setSelectedServiceIds] = useState<string[]>([]);
  const [serviceCategory, setServiceCategory] = useState<string>('__all__');
  const { getName } = useUserNames(teamMembers || []);

  const serviceCategories = React.useMemo(() => {
    if (!services) return [];
    const cats = [...new Set(services.map(s => s.category).filter(Boolean))] as string[];
    return cats.sort();
  }, [services]);

  const filteredServices = React.useMemo(() => {
    if (!services) return [];
    if (serviceCategory === '__all__') return services;
    return services.filter(s => s.category === serviceCategory);
  }, [services, serviceCategory]);

  const serviceBudget = React.useMemo(() => {
    if (!services || selectedServiceIds.length === 0) return null;
    return services
      .filter(s => selectedServiceIds.includes(s.id))
      .reduce((sum, s) => sum + (s.price || 0), 0);
  }, [services, selectedServiceIds]);

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    if (teamId && teamId !== '__none__') {
      formData.set('teamId', teamId);
    }
    if (custId && custId !== '__none__') {
      formData.set('customerId', custId);
    }
    if (responsibleUserId && responsibleUserId !== '__none__') {
      formData.set('responsibleUserId', responsibleUserId);
    }
    formData.set('isRecurring', isRecurring ? 'true' : 'false');
    if (isRecurring) formData.set('recurringFrequency', recurringFrequency);
    formData.set('memberUserIds', JSON.stringify(memberUserIds));
    formData.set('selectedServiceIds', JSON.stringify(selectedServiceIds));
    // Override budget with computed service total if services are selected
    if (serviceBudget !== null) {
      formData.set('budget', String(serviceBudget));
    }
    onSubmit(formData);
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div>
        <Label htmlFor="name">Emri i Projektit</Label>
        <Input id="name" name="name" required defaultValue={initialData?.name} placeholder="p.sh. Website Redesign" />
      </div>

      <div>
        <Label htmlFor="description">P├½rshkrimi</Label>
        <Textarea id="description" name="description" defaultValue={initialData?.description} placeholder="P├½rshkruaj projektin..." rows={3} />
      </div>

      <div>
        <Label htmlFor="status">Statusi</Label>
        <Select name="status" defaultValue={initialData?.status || 'Planning'}>
          <SelectTrigger>
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="Planning">Planifikim</SelectItem>
            <SelectItem value="Active">Aktiv</SelectItem>
            <SelectItem value="In Review">N├½n Vler├½sim</SelectItem>
            <SelectItem value="On Hold">N├½ pritje</SelectItem>
            <SelectItem value="Completed">P├½rfunduar</SelectItem>
            <SelectItem value="Archived">Arkivuar</SelectItem>
            <SelectItem value="Cancelled">Anuluar</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div>
        <Label htmlFor="teamId">Ekipi</Label>
        <Select value={teamId} onValueChange={setTeamId}>
          <SelectTrigger>
            <SelectValue placeholder="Zgjidh ekipin" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="__none__">Asnj├½ ekip</SelectItem>
            {teams.map(team => (
              <SelectItem key={team.id} value={team.id}>{team.name}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Customer */}
      <div>
        <Label htmlFor="customerId">Klienti</Label>
        <Select value={custId} onValueChange={setCustId}>
          <SelectTrigger>
            <SelectValue placeholder="Zgjidh klientin" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="__none__">Asnj├½ klient</SelectItem>
            {customers?.map(c => (
              <SelectItem key={c.id} value={c.id}>{c.name} {c.company && `(${c.company})`}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Services ΓåÆ Budget */}
      {services && services.length > 0 && (
        <div>
          <Label>Sh├½rbimet e Projektit</Label>
          <p className="text-xs text-muted-foreground mb-2">Zgjidh kategorin├½ dhe m├½pas sh├½rbimet ΓÇö totali llogaritet automatikisht si buxhet</p>

          {/* Category filter pills */}
          {serviceCategories.length > 0 && (
            <div className="flex flex-wrap gap-1.5 mb-2">
              <button
                type="button"
                onClick={() => setServiceCategory('__all__')}
                className={`px-2.5 py-1 rounded-full text-xs font-medium border transition-colors ${
                  serviceCategory === '__all__'
                    ? 'bg-primary text-primary-foreground border-primary'
                    : 'bg-muted text-muted-foreground border-border hover:bg-muted/70'
                }`}
              >
                T├½ gjitha
              </button>
              {serviceCategories.map(cat => (
                <button
                  key={cat}
                  type="button"
                  onClick={() => setServiceCategory(cat)}
                  className={`px-2.5 py-1 rounded-full text-xs font-medium border transition-colors ${
                    serviceCategory === cat
                      ? 'bg-primary text-primary-foreground border-primary'
                      : 'bg-muted text-muted-foreground border-border hover:bg-muted/70'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          )}

          {/* Services list filtered by category */}
          <div className="space-y-1.5 max-h-44 overflow-y-auto border rounded-md p-2">
            {filteredServices.length === 0 ? (
              <p className="text-xs text-muted-foreground py-2 text-center">Nuk ka sh├½rbime n├½ k├½t├½ kategori</p>
            ) : filteredServices.map(s => (
              <label key={s.id} className="flex items-center gap-2 cursor-pointer hover:bg-muted/50 px-2 py-1 rounded">
                <input
                  type="checkbox"
                  className="w-4 h-4 accent-primary"
                  checked={selectedServiceIds.includes(s.id)}
                  onChange={(e) => {
                    setSelectedServiceIds(prev =>
                      e.target.checked ? [...prev, s.id] : prev.filter(id => id !== s.id)
                    );
                  }}
                />
                <div className="flex-1 flex items-center justify-between gap-2">
                  <div className="min-w-0">
                    <span className="text-sm font-medium">{s.name || s.title}</span>
                    {s.category && serviceCategory === '__all__' && (
                      <span className="ml-1.5 text-[10px] text-muted-foreground bg-muted px-1.5 py-0.5 rounded">{s.category}</span>
                    )}
                  </div>
                  <span className="text-sm text-primary font-medium shrink-0">{(s.price || 0).toLocaleString()} {s.currency || 'ALL'}</span>
                </div>
              </label>
            ))}
          </div>

          {selectedServiceIds.length > 0 && (
            <p className="text-xs text-primary font-medium mt-1">
              {selectedServiceIds.length} sh├½rbim{selectedServiceIds.length !== 1 ? 'e' : ''} zgjedhur ┬╖ Total: {serviceBudget?.toLocaleString()} {services[0]?.currency || 'ALL'}
            </p>
          )}
        </div>
      )}

      {/* Budget */}
      <div>
        <Label htmlFor="budget">Buxheti / T├½ Ardhurat e Projektit (L)</Label>
        <Input
          id="budget"
          name="budget"
          type="number"
          step="0.01"
          value={serviceBudget !== null ? String(serviceBudget) : undefined}
          defaultValue={serviceBudget !== null ? undefined : ((initialData as any)?.budget || '')}
          onChange={() => {}}
          placeholder="0.00"
          readOnly={serviceBudget !== null}
          className={serviceBudget !== null ? 'bg-muted cursor-not-allowed' : ''}
        />
        <p className="text-xs text-muted-foreground mt-1">
          {serviceBudget !== null ? 'Llogaritet automatikisht nga sh├½rbimet e zgjedhura' : 'Shuma q├½ projekti gjeneron si t├½ ardhura'}
        </p>
      </div>

      {/* Responsible Person */}
      {teamMembers && teamMembers.length > 0 && (
        <div>
          <Label htmlFor="responsibleUserId">P├½rgjegj├½si i Projektit</Label>
          <Select value={responsibleUserId} onValueChange={setResponsibleUserId}>
            <SelectTrigger>
              <SelectValue placeholder="Zgjidh punonj├½sin" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="__none__">Asnj├½ i caktuar</SelectItem>
              {teamMembers.map(m => (
                <SelectItem key={m.id} value={m.userId}>
                  {getName(m.userId)} ({m.role})
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <p className="text-xs text-muted-foreground mt-1">Punonj├½si q├½ merr kredit p├½r k├½t├½ projekt n├½ llogaritjen e bonusit</p>
        </div>
      )}

      {/* Project Members */}
      {teamMembers && teamMembers.length > 0 && (
        <div>
          <Label>An├½tar├½t e Projektit</Label>
          <p className="text-xs text-muted-foreground mb-2">Zgjidh personat q├½ do t├½ marrin pjes├½ n├½ k├½t├½ projekt</p>
          <div className="space-y-2 max-h-48 overflow-y-auto border rounded-md p-2">
            {teamMembers.map(m => (
              <label key={m.id} className="flex items-center gap-2 cursor-pointer hover:bg-muted/50 px-2 py-1 rounded">
                <input
                  type="checkbox"
                  className="w-4 h-4 accent-primary"
                  checked={memberUserIds.includes(m.userId)}
                  onChange={(e) => {
                    setMemberUserIds(prev =>
                      e.target.checked ? [...prev, m.userId] : prev.filter(id => id !== m.userId)
                    );
                  }}
                />
                <div className="flex items-center gap-2 flex-1">
                  <div className="w-7 h-7 rounded-full bg-primary/10 flex items-center justify-center text-xs font-medium text-primary">
                    {getName(m.userId).charAt(0).toUpperCase()}
                  </div>
                  <div>
                    <p className="text-sm font-medium">{getName(m.userId)}</p>
                    <p className="text-xs text-muted-foreground">{m.role}</p>
                  </div>
                </div>
              </label>
            ))}
          </div>
          {memberUserIds.length > 0 && (
            <p className="text-xs text-primary mt-1">{memberUserIds.length} person{memberUserIds.length !== 1 ? 'a' : ''} t├½ zgjedhur</p>
          )}
        </div>
      )}

      {/* Recurring Project */}
      <div className="flex items-center justify-between py-2 px-3 rounded-lg bg-muted/40">
        <div>
          <p className="text-sm font-medium">Projekt Periodik</p>
          <p className="text-xs text-muted-foreground">Projekti rip├½rs├½ritet automatikisht ├ºdo jav├½/muaj</p>
        </div>
        <button
          type="button"
          role="switch"
          aria-checked={isRecurring}
          onClick={() => setIsRecurring(!isRecurring)}
          className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${
            isRecurring ? 'bg-primary' : 'bg-muted-foreground/30'
          }`}
        >
          <span className={`inline-block h-3.5 w-3.5 transform rounded-full bg-white transition-transform ${
            isRecurring ? 'translate-x-4' : 'translate-x-1'
          }`} />
        </button>
      </div>

      {isRecurring && (
        <div>
          <Label>Frekuenca e P├½rs├½ritjes</Label>
          <Select value={recurringFrequency} onValueChange={setRecurringFrequency}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="weekly">Javore (├ºdo jav├½)</SelectItem>
              <SelectItem value="monthly">Mujore (├ºdo muaj)</SelectItem>
            </SelectContent>
          </Select>
          <p className="text-xs text-muted-foreground mt-1">
            Kur t├½ gjitha detyrat mbarojn├½, projekti sh├½nohet si kompletuar p├½r at├½ periudh├½ dhe rifillon automatikisht.
          </p>
        </div>
      )}

      <Button type="submit" className="w-full">
        {initialData ? 'Ruaj Ndryshimet' : 'Krijo Projektin'}
      </Button>
    </form>
  );
};

export default ProjectsView;

import React, { useMemo } from 'react';
import { TrendingUp, TrendingDown, DollarSign, Users, CheckCircle, Clock, Building2, Receipt, Target, FileText, UserPlus, CreditCard, ClipboardList } from 'lucide-react';
import { Card } from '../components/ui/card';
import { useCollection } from '../hooks/useFirestore';
import { Badge } from '../components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../components/ui/tabs';
import {
  BarChart as RechartsBarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer,
  LineChart as RechartsLineChart, Line, Area, AreaChart,
  PieChart, Pie, Cell, Legend
} from 'recharts';
import type { Invoice, Project, Team, Expense, Service, InvoiceItem, Task, Lead, Customer, Activity, TeamMember } from '../types';

// ΓöÇΓöÇ Recharts Bar Chart ΓöÇΓöÇ
const BarChart: React.FC<{ data: { label: string; value: number; color?: string }[]; height?: number }> = ({ data, height = 200 }) => {
  if (!data.length) return <div className="text-muted-foreground text-center py-8">Nuk ka t├½ dh├½na</div>;
  const defaultColor = '#6366f1';
  return (
    <ResponsiveContainer width="100%" height={height}>
      <RechartsBarChart data={data} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
        <XAxis dataKey="label" tick={{ fontSize: 11 }} tickLine={false} axisLine={false} />
        <YAxis tick={{ fontSize: 11 }} tickLine={false} axisLine={false} width={40} tickFormatter={(v: number) => v >= 1000 ? `${(v / 1000).toFixed(0)}k` : String(v)} />
        <Tooltip formatter={(value: number) => value.toLocaleString()} />
        <Bar dataKey="value" radius={[4, 4, 0, 0]}>
          {data.map((d, i) => (
            <Cell key={i} fill={d.color || defaultColor} fillOpacity={0.85} />
          ))}
        </Bar>
      </RechartsBarChart>
    </ResponsiveContainer>
  );
};

// ΓöÇΓöÇ Recharts Area/Line Chart ΓöÇΓöÇ
const LineChart: React.FC<{ data: { label: string; value: number }[]; height?: number; color?: string }> = ({ data, height = 180, color = '#22c55e' }) => {
  if (!data.length) return <div className="text-muted-foreground text-center py-8">Nuk ka t├½ dh├½na</div>;
  return (
    <ResponsiveContainer width="100%" height={height}>
      <AreaChart data={data} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
        <defs>
          <linearGradient id={`grad-${color.replace('#', '')}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={color} stopOpacity={0.3} />
            <stop offset="100%" stopColor={color} stopOpacity={0.02} />
          </linearGradient>
        </defs>
        <XAxis dataKey="label" tick={{ fontSize: 11 }} tickLine={false} axisLine={false} />
        <YAxis tick={{ fontSize: 11 }} tickLine={false} axisLine={false} width={40} tickFormatter={(v: number) => v >= 1000 ? `${(v / 1000).toFixed(0)}k` : String(v)} />
        <Tooltip formatter={(value: number) => value.toLocaleString()} />
        <Area type="monotone" dataKey="value" stroke={color} strokeWidth={2.5} fill={`url(#grad-${color.replace('#', '')})`} dot={{ r: 4, fill: '#fff', stroke: color, strokeWidth: 2 }} />
      </AreaChart>
    </ResponsiveContainer>
  );
};

// ΓöÇΓöÇ Recharts Donut/Pie Chart ΓöÇΓöÇ
const DonutChart: React.FC<{ segments: { label: string; value: number; color: string }[]; size?: number }> = ({ segments, size = 160 }) => {
  const total = segments.reduce((s, seg) => s + seg.value, 0);
  return (
    <div className="flex items-center gap-4">
      <ResponsiveContainer width={size} height={size}>
        <PieChart>
          <Pie data={segments} dataKey="value" nameKey="label" cx="50%" cy="50%" innerRadius="55%" outerRadius="90%" paddingAngle={2} strokeWidth={0}>
            {segments.map((seg, i) => (
              <Cell key={i} fill={seg.color} />
            ))}
          </Pie>
          <Tooltip formatter={(value: number) => value.toLocaleString()} />
          <text x="50%" y="45%" textAnchor="middle" dominantBaseline="middle" className="fill-foreground text-lg font-bold">{total}</text>
          <text x="50%" y="60%" textAnchor="middle" dominantBaseline="middle" className="fill-muted-foreground text-[10px]">Gjithsej</text>
        </PieChart>
      </ResponsiveContainer>
      <div className="space-y-1.5">
        {segments.map((seg, i) => (
          <div key={i} className="flex items-center gap-2 text-sm">
            <div className="w-3 h-3 rounded-sm" style={{ background: seg.color }} />
            <span className="text-muted-foreground">{seg.label}</span>
            <span className="font-medium ml-auto">{seg.value}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

const ReportsView: React.FC = () => {
  const { data: invoices, loading: invoicesLoading } = useCollection<Invoice>('invoices', { skipTeamFilter: true });
  const { data: projects, loading: projectsLoading } = useCollection<Project>('projects', { skipTeamFilter: true });
  const { data: teams } = useCollection<Team>('teams');
  const { data: expenses, loading: expensesLoading } = useCollection<Expense>('expenses', { skipTeamFilter: true });
  const { data: services } = useCollection<Service>('services', { skipTeamFilter: true });
  const { data: invoiceItems } = useCollection<InvoiceItem>('invoiceItems', { skipTeamFilter: true });
  const { data: tasks } = useCollection<Task>('tasks', { skipTeamFilter: true });
  const { data: leads } = useCollection<Lead>('leads', { skipTeamFilter: true });
  const { data: customers } = useCollection<Customer>('customers', { skipTeamFilter: true });
  const { data: activities } = useCollection<Activity>('activities', { skipTeamFilter: true });
  const { data: teamMembers } = useCollection<TeamMember>('teamMembers', {
    where: [{ field: 'status', operator: '==', value: 'Active' }],
  });

  // ΓöÇΓöÇ Monthly salary cost from all active team members ΓöÇΓöÇ
  const totalMonthlySalary = useMemo(() => {
    if (!teamMembers) return 0;
    return teamMembers.reduce((sum, m) => sum + (m.monthlySalary || 0), 0);
  }, [teamMembers]);

  // ΓöÇΓöÇ Revenue by Month (last 6 months) ΓöÇΓöÇ
  const revenueByMonth = useMemo(() => {
    if (!invoices) return [];
    const months: { label: string; value: number }[] = [];
    const now = new Date();
    for (let i = 5; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const label = d.toLocaleDateString('sq-AL', { month: 'short' });
      const monthInvoices = invoices.filter(inv => {
        if (inv.status !== 'Paid') return false;
        // Prefer paidAt date; fall back to updatedAt/createdAt
        const paidDate = inv.paidAt ? (inv.paidAt instanceof Date ? inv.paidAt : new Date(inv.paidAt))
          : (inv.updatedAt ? (inv.updatedAt instanceof Date ? inv.updatedAt : new Date(inv.updatedAt))
          : (inv.createdAt instanceof Date ? inv.createdAt : new Date(inv.createdAt)));
        return paidDate.getMonth() === d.getMonth() && paidDate.getFullYear() === d.getFullYear();
      });
      months.push({ label, value: monthInvoices.reduce((s, inv) => s + (inv.total ?? inv.amount ?? 0), 0) });
    }
    return months;
  }, [invoices]);

  // ΓöÇΓöÇ Expenses by Month ΓöÇΓöÇ
  const expensesByMonth = useMemo(() => {
    if (!expenses) return [];
    const months: { label: string; value: number }[] = [];
    const now = new Date();
    for (let i = 5; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const label = d.toLocaleDateString('sq-AL', { month: 'short' });
      const monthExpenses = expenses.filter(exp => {
        const cd = exp.createdAt instanceof Date ? exp.createdAt : new Date(exp.createdAt);
        return cd.getMonth() === d.getMonth() && cd.getFullYear() === d.getFullYear();
      });
      months.push({ label, value: monthExpenses.reduce((s, exp) => s + (exp.amount ?? 0), 0) + totalMonthlySalary });
    }
    return months;
  }, [expenses, totalMonthlySalary]);

  // ΓöÇΓöÇ Lead Funnel ΓöÇΓöÇ
  const leadFunnel = useMemo(() => {
    if (!leads) return [];
    const statuses = [
      { status: 'New', label: 'T├½ Reja', color: '#3b82f6' },
      { status: 'Contacted', label: 'Kontaktuar', color: '#8b5cf6' },
      { status: 'Qualified', label: 'Kualifikuar', color: '#f59e0b' },
      { status: 'Proposal', label: 'Propozim', color: '#6366f1' },
      { status: 'Won', label: 'Fituar', color: '#22c55e' },
      { status: 'Lost', label: 'Humbur', color: '#ef4444' },
    ];
    return statuses.map(s => ({
      label: s.label,
      value: leads.filter(l => l.status === s.status).length,
      color: s.color,
    }));
  }, [leads]);

  // ΓöÇΓöÇ Invoice Status Distribution ΓöÇΓöÇ
  const invoiceStatusDist = useMemo(() => {
    if (!invoices) return [];
    return [
      { label: 'Paguar', value: invoices.filter(i => i.status === 'Paid').length, color: '#22c55e' },
      { label: 'N├½ Pritje', value: invoices.filter(i => i.status === 'Pending').length, color: '#f59e0b' },
      { label: 'Vonuar', value: invoices.filter(i => i.status === 'Overdue').length, color: '#ef4444' },
      { label: 'Draft', value: invoices.filter(i => i.status === 'Draft').length, color: '#94a3b8' },
    ];
  }, [invoices]);

  // ΓöÇΓöÇ Project Performance (real) ΓöÇΓöÇ
  const projectPerformance = useMemo(() => {
    if (!projects || !tasks) return [];
    return projects
      .filter(p => p.status === 'Active' || p.status === 'Planning')
      .slice(0, 6)
      .map(p => {
        const projectTasks = tasks.filter(t => t.projectId === p.id);
        const done = projectTasks.filter(t => t.status === 'Done').length;
        const total = projectTasks.length;
        const pct = total > 0 ? Math.round((done / total) * 100) : 0;
        // Revenue = sum of paid invoices linked to this project
        const revenue = invoices
          ? invoices.filter(inv => inv.projectId === p.id && inv.status === 'Paid')
              .reduce((s, inv) => s + (inv.total ?? inv.amount ?? 0), 0)
          : 0;
        return { name: p.name, progress: pct, done, total, budget: p.budget, spent: p.spent, revenue };
      });
  }, [projects, tasks, invoices]);

  // ΓöÇΓöÇ Revenue by Department ΓöÇΓöÇ
  const revenueByDepartment = useMemo(() => {
    if (!invoices || !invoiceItems || !services) return [];
    const deptMap = new Map<string, { total: number; paid: number; count: number }>();
    invoices.forEach(invoice => {
      const items = invoiceItems.filter(item => item.invoiceId === invoice.id);
      items.forEach(item => {
        const service = services.find(s => s.id === item.serviceId);
        const dept = service?.category || 'General';
        const current = deptMap.get(dept) || { total: 0, paid: 0, count: 0 };
        current.total += item.totalPrice;
        current.count++;
        if (invoice.status === 'Paid') current.paid += item.totalPrice;
        deptMap.set(dept, current);
      });
    });
    return Array.from(deptMap.entries()).map(([dept, stats]) => ({ department: dept, ...stats })).sort((a, b) => b.total - a.total);
  }, [invoices, invoiceItems, services]);

  // ΓöÇΓöÇ KPI Calculations ΓöÇΓöÇ
  const totalRevenue = invoices?.filter(inv => inv.status === 'Paid').reduce((sum, inv) => sum + (inv.total ?? inv.amount ?? 0), 0) || 0;
  const paidRevenue = totalRevenue;
  const projectedRevenue = invoices?.filter(inv => inv.status === 'Pending' || inv.status === 'Draft').reduce((sum, inv) => sum + (inv.total ?? inv.amount ?? 0), 0) || 0;
  const totalExpenses = (expenses?.reduce((sum, exp) => sum + (exp.amount ?? 0), 0) || 0) + totalMonthlySalary;
  const profit = paidRevenue - totalExpenses;
  const activeProjects = projects?.filter(p => p.status === 'Active').length || 0;
  const totalCustomers = customers?.length || 0;
  const wonLeads = leads?.filter(l => l.status === 'Won').length || 0;
  const totalLeads = leads?.length || 0;
  const conversionRate = totalLeads > 0 ? Math.round((wonLeads / totalLeads) * 100) : 0;

  // ΓöÇΓöÇ Last month comparison for trends (Paid invoices only, by paidAt date) ΓöÇΓöÇ
  const lastMonthRevenue = useMemo(() => {
    if (!invoices) return 0;
    const now = new Date();
    const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const lastMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0);
    return invoices.filter(inv => {
      if (inv.status !== 'Paid') return false;
      const d = inv.paidAt ? (inv.paidAt instanceof Date ? inv.paidAt : new Date(inv.paidAt))
        : (inv.updatedAt instanceof Date ? inv.updatedAt : new Date(inv.updatedAt));
      return d >= lastMonth && d <= lastMonthEnd;
    }).reduce((s, inv) => s + (inv.total ?? inv.amount ?? 0), 0);
  }, [invoices]);

  const thisMonthRevenue = useMemo(() => {
    if (!invoices) return 0;
    const now = new Date();
    const thisMonth = new Date(now.getFullYear(), now.getMonth(), 1);
    return invoices.filter(inv => {
      if (inv.status !== 'Paid') return false;
      const d = inv.paidAt ? (inv.paidAt instanceof Date ? inv.paidAt : new Date(inv.paidAt))
        : (inv.updatedAt instanceof Date ? inv.updatedAt : new Date(inv.updatedAt));
      return d >= thisMonth;
    }).reduce((s, inv) => s + (inv.total ?? inv.amount ?? 0), 0);
  }, [invoices]);

  const revenueChange = lastMonthRevenue > 0 ? Math.round(((thisMonthRevenue - lastMonthRevenue) / lastMonthRevenue) * 100) : 0;

  // ΓöÇΓöÇ Real Activity Feed ΓöÇΓöÇ
  const recentActivities = useMemo(() => {
    if (!activities) return [];
    return [...activities].sort((a, b) => {
      const ta = a.createdAt instanceof Date ? a.createdAt.getTime() : 0;
      const tb = b.createdAt instanceof Date ? b.createdAt.getTime() : 0;
      return tb - ta;
    }).slice(0, 10);
  }, [activities]);

  const timeAgo = (date: Date) => {
    const seconds = Math.floor((new Date().getTime() - new Date(date).getTime()) / 1000);
    if (seconds < 60) return 'tani';
    if (seconds < 3600) return `${Math.floor(seconds / 60)} min`;
    if (seconds < 86400) return `${Math.floor(seconds / 3600)} or├½`;
    if (seconds < 604800) return `${Math.floor(seconds / 86400)} dit├½`;
    return new Date(date).toLocaleDateString('sq-AL');
  };

  const getActivityIcon = (type: string) => {
    switch (type) {
      case 'invoice_created': case 'invoice_paid': return <FileText className="w-4 h-4 text-blue-500" />;
      case 'lead_created': case 'lead_converted': return <UserPlus className="w-4 h-4 text-purple-500" />;
      case 'task_completed': return <CheckCircle className="w-4 h-4 text-green-500" />;
      case 'project_created': return <Target className="w-4 h-4 text-indigo-500" />;
      case 'customer_created': return <Users className="w-4 h-4 text-teal-500" />;
      case 'expense_added': return <Receipt className="w-4 h-4 text-red-500" />;
      case 'meeting': case 'call': return <Clock className="w-4 h-4 text-orange-500" />;
      default: return <ClipboardList className="w-4 h-4 text-gray-500" />;
    }
  };

  const isLoading = invoicesLoading || projectsLoading || expensesLoading;

  if (isLoading) {
    return (
      <div className="space-y-8">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {[1, 2, 3, 4].map(i => (
            <div key={i} className="p-6 bg-card rounded-lg border space-y-3">
              <div className="h-4 w-28 skeleton rounded" />
              <div className="h-8 w-24 skeleton rounded" />
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8">
      {/* KPI Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4 lg:gap-6">
        <Card className="p-5 space-y-2 border-l-4 border-l-green-500">
          <div className="flex items-center justify-between">
            <p className="text-sm text-muted-foreground">T├½ Ardhura (Paguar)</p>
            <DollarSign className="w-5 h-5 text-green-500" />
          </div>
          <p className="text-2xl font-bold">{totalRevenue.toLocaleString()} ALL</p>
          <div className="flex items-center gap-1 text-xs">
            {revenueChange >= 0 ? <TrendingUp className="w-3 h-3 text-green-500" /> : <TrendingDown className="w-3 h-3 text-red-500" />}
            <span className={revenueChange >= 0 ? 'text-green-600' : 'text-red-600'}>{revenueChange >= 0 ? '+' : ''}{revenueChange}%</span>
            <span className="text-muted-foreground">nga muaji i kaluar</span>
          </div>
        </Card>
        <Card className="p-5 space-y-2 border-l-4 border-l-amber-400">
          <div className="flex items-center justify-between">
            <p className="text-sm text-muted-foreground">Parashikuara</p>
            <TrendingUp className="w-5 h-5 text-amber-400" />
          </div>
          <p className="text-2xl font-bold text-amber-500">{projectedRevenue.toLocaleString()} ALL</p>
          <p className="text-xs text-muted-foreground">Fatura Draft + N├½ Pritje</p>
        </Card>
        <Card className="p-5 space-y-2 border-l-4 border-l-red-500">
          <div className="flex items-center justify-between">
            <p className="text-sm text-muted-foreground">Shpenzime (Gjithsej)</p>
            <Receipt className="w-5 h-5 text-red-500" />
          </div>
          <p className="text-2xl font-bold">{totalExpenses.toLocaleString()} ALL</p>
          <p className="text-xs text-muted-foreground">Shpenzime + Rroga ({totalMonthlySalary.toLocaleString()} ALL/muaj)</p>
        </Card>
        <Card className="p-5 space-y-2 border-l-4 border-l-indigo-500">
          <div className="flex items-center justify-between">
            <p className="text-sm text-muted-foreground">Fitimi Neto</p>
            <TrendingUp className="w-5 h-5 text-indigo-500" />
          </div>
          <p className={`text-2xl font-bold ${profit >= 0 ? 'text-green-600' : 'text-red-600'}`}>{profit.toLocaleString()} ALL</p>
          <p className="text-xs text-muted-foreground">Paguar - Shpenzime</p>
        </Card>
        <Card className="p-5 space-y-2 border-l-4 border-l-blue-500">
          <div className="flex items-center justify-between">
            <p className="text-sm text-muted-foreground">Konvertim Lead</p>
            <Target className="w-5 h-5 text-blue-500" />
          </div>
          <p className="text-2xl font-bold">{conversionRate}%</p>
          <p className="text-xs text-muted-foreground">{wonLeads} / {totalLeads} leads ┬╖ {totalCustomers} klient├½</p>
        </Card>
      </div>

      {/* Charts Tabs */}
      <Tabs defaultValue="revenue" className="space-y-4">
        <TabsList>
          <TabsTrigger value="revenue">T├½ Ardhura</TabsTrigger>
          <TabsTrigger value="expenses">Shpenzime</TabsTrigger>
          <TabsTrigger value="leads">Lead Funnel</TabsTrigger>
          <TabsTrigger value="invoices">Faturat</TabsTrigger>
        </TabsList>

        <TabsContent value="revenue">
          <Card className="p-6">
            <h3 className="text-lg font-semibold mb-4">T├½ Ardhurat - 6 Muajt e Fundit</h3>
            <LineChart data={revenueByMonth} color="#22c55e" />
          </Card>
        </TabsContent>
        <TabsContent value="expenses">
          <Card className="p-6">
            <h3 className="text-lg font-semibold mb-4">Shpenzimet - 6 Muajt e Fundit</h3>
            <BarChart data={expensesByMonth.map(d => ({ ...d, color: '#ef4444' }))} />
          </Card>
        </TabsContent>
        <TabsContent value="leads">
          <Card className="p-6">
            <h3 className="text-lg font-semibold mb-4">Lead Pipeline</h3>
            <BarChart data={leadFunnel} />
          </Card>
        </TabsContent>
        <TabsContent value="invoices">
          <Card className="p-6">
            <h3 className="text-lg font-semibold mb-4">Statusi i Faturave</h3>
            <DonutChart segments={invoiceStatusDist} />
          </Card>
        </TabsContent>
      </Tabs>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Real Project Performance */}
        <Card className="p-6 space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-semibold">Performanca e Projekteve</h3>
            <Badge variant="secondary">{activeProjects} aktive</Badge>
          </div>
          {projectPerformance.length === 0 ? (
            <p className="text-sm text-muted-foreground py-4 text-center">Nuk ka projekte aktive</p>
          ) : (
            <div className="space-y-4">
              {projectPerformance.map(p => (
                <div key={p.name} className="space-y-1.5">
                  <div className="flex items-center justify-between text-sm">
                    <span className="font-medium truncate max-w-[60%]">{p.name}</span>
                    <div className="flex items-center gap-2">
                      <span className="text-muted-foreground">{p.done}/{p.total} detyra</span>
                      <span className="font-semibold">{p.progress}%</span>
                    </div>
                  </div>
                  <div className="w-full h-2.5 bg-muted rounded-full overflow-hidden">
                    <div
                      className="h-full rounded-full transition-all duration-500"
                      style={{
                        width: `${p.progress}%`,
                        background: p.progress >= 80 ? '#22c55e' : p.progress >= 40 ? '#6366f1' : '#f59e0b'
                      }}
                    />
                  </div>
                  {(p.budget != null || p.revenue > 0) && (
                    <div className="text-xs text-muted-foreground flex justify-between">
                      {p.revenue > 0 && <span className="text-green-600 font-medium">T├½ ardhura: {p.revenue.toLocaleString()} ALL</span>}
                      {p.budget != null && <span>Buxheti: {p.budget.toLocaleString()} ALL</span>}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </Card>

        {/* Real Activity Timeline */}
        <Card className="p-6 space-y-4">
          <h3 className="text-lg font-semibold">Aktiviteti i Fundit</h3>
          {recentActivities.length === 0 ? (
            <p className="text-sm text-muted-foreground text-center py-4">Nuk ka aktivitet akoma. Veprimet do shfaqen automatikisht ketu.</p>
          ) : (
            <div className="space-y-3">
              {recentActivities.map(act => (
                <div key={act.id} className="flex items-start gap-3 py-2 border-b last:border-0">
                  <div className="mt-0.5">{getActivityIcon(act.type)}</div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium">{act.title}</p>
                    {act.description && <p className="text-xs text-muted-foreground mt-0.5">{act.description}</p>}
                  </div>
                  <span className="text-xs text-muted-foreground whitespace-nowrap">{timeAgo(act.createdAt)}</span>
                </div>
              ))}
            </div>
          )}
        </Card>
      </div>

      {/* Revenue by Department */}
      <Card className="p-6 space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="text-lg font-semibold">T├½ Ardhura sipas Departamentit</h3>
          <Badge variant="secondary">{revenueByDepartment.length} departamente</Badge>
        </div>
        {revenueByDepartment.length === 0 ? (
          <p className="text-sm text-muted-foreground text-center py-8">Krijoni fatura me sh├½rbime p├½r t├½ par├½ ndarjen.</p>
        ) : (
          <div className="space-y-3">
            {revenueByDepartment.map(dept => {
              const paidPct = dept.total > 0 ? (dept.paid / dept.total) * 100 : 0;
              return (
                <div key={dept.department} className="space-y-1.5">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <Building2 className="h-4 w-4 text-muted-foreground" />
                      <span className="font-medium">{dept.department}</span>
                      <Badge variant="outline" className="text-xs">{dept.count} fatura</Badge>
                    </div>
                    <div className="text-right">
                      <span className="font-semibold">{dept.total.toLocaleString()} ALL</span>
                      <div className="text-xs text-muted-foreground">{dept.paid.toLocaleString()} paguar</div>
                    </div>
                  </div>
                  <div className="w-full h-2 bg-muted rounded-full overflow-hidden">
                    <div className="h-full bg-green-500 rounded-full transition-all" style={{ width: `${paidPct}%` }} />
                  </div>
                </div>
              );
            })}
            <div className="pt-3 border-t space-y-2">
              <div className="flex justify-between text-sm font-semibold">
                <span>Totale</span>
                <span>{totalRevenue.toLocaleString()} ALL</span>
              </div>
              <div className="flex justify-between text-sm font-semibold">
                <span>Fitimi Neto</span>
                <span className={profit >= 0 ? 'text-green-600' : 'text-red-600'}>{profit.toLocaleString()} ALL</span>
              </div>
            </div>
          </div>
        )}
      </Card>
    </div>
  );
};

