      <div>
        <Label htmlFor="displayName">Emri dhe Mbiemri</Label>
        <Input
          id="displayName"
          value={displayName}
          onChange={e => setDisplayName(e.target.value)}
          placeholder="p.sh. Emir Mbiemri"
        />
        <p className="text-xs text-muted-foreground mt-1">Ky em├½r shfaqet kudo n├½ platform├½</p>
      </div>

      {/* Email field */}
      <div>
        <Label htmlFor="editEmail">Email</Label>
        <Input
          id="editEmail"
          type="email"
          value={email}
          onChange={e => setEmail(e.target.value)}
          placeholder="email@shembull.com"
        />
        <p className="text-xs text-muted-foreground mt-1">P├½rdoret p├½r ftesa dhe njoftime</p>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label htmlFor="editRole">Roli</Label>
          <Select value={role} onValueChange={setRole}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="Admin">
                <div className="flex items-center gap-2">
                  <Shield className="w-4 h-4" />
