                      <div className="w-full bg-muted rounded-full h-2">
                        <div
                          className="bg-primary h-2 rounded-full"
                          style={{ width: `${goal.progress || 0}%` }}
                        />
                      </div>
                    </div>
                  </div>
                ))
              ) : (
                <p className="text-center text-muted-foreground py-8">Nuk ka objektiva</p>
              )}
            </TabsContent>
          </Tabs>
        </Card>
      </div>
    </div>
  );
};

export default UserProfileView;

import React, { useState, useEffect, useRef } from 'react';
import { useClientPortal } from '../../hooks/useClientPortal';
import { useCollection, useMutation } from '../../hooks/useFirestore';
import { useAuth } from '../../contexts/AuthContext';
import { Input } from '../../components/ui/input';
import { Button } from '../../components/ui/button';
import { ScrollArea } from '../../components/ui/scroll-area';
import { Badge } from '../../components/ui/badge';
import { Send, MessageSquare, Paperclip, X, FileIcon, FolderKanban, HelpCircle, AlertCircle, RefreshCw, ChevronRight, Reply, SmilePlus } from 'lucide-react';
import { useToast } from '../../hooks/use-toast';
import type { ChatMessage, Project } from '../../types';

const EMOJI_REACTIONS = ['≡ƒæì', 'Γ¥ñ∩╕Å', '≡ƒÿé', '≡ƒÿ«', '≡ƒÿó', '≡ƒöÑ'];

const PortalChatView: React.FC = () => {
  const { user } = useAuth();
  const { customerId } = useClientPortal();
  const { toast } = useToast();
  const [messageText, setMessageText] = useState('');
  const [attachmentUrl, setAttachmentUrl] = useState('');
  const [showAttachmentInput, setShowAttachmentInput] = useState(false);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [replyingTo, setReplyingTo] = useState<any>(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Fetch projects assigned to this customer
  const { data: customerProjects } = useCollection<Project>('projects', {
    where: [{ field: 'customerId', operator: '==', value: customerId || '' }],
    skipTeamFilter: true,
  });

  // Channel includes project if selected, otherwise general client channel
  const channelId = customerId
    ? (selectedProjectId
      ? `client-${customerId}-project-${selectedProjectId}`
      : `client-${customerId}`)
    : '';

  const { data: rawMessages, loading } = useCollection<ChatMessage>('messages', {
    where: [{ field: 'channelId', operator: '==', value: channelId }],
    skipTeamFilter: true,
  });

  // Sort client-side to avoid Firestore composite index requirement
  const messages = React.useMemo(() => {
    if (!rawMessages) return [];
    return [...rawMessages]
      .filter(m => !(m as any).deletedAt)
      .sort((a, b) => {
        const ta = a.createdAt instanceof Date ? a.createdAt.getTime() : (a.createdAt as any)?.toMillis?.() ?? 0;
        const tb = b.createdAt instanceof Date ? b.createdAt.getTime() : (b.createdAt as any)?.toMillis?.() ?? 0;
        return ta - tb;
      });
  }, [rawMessages]);

  // Fetch team members for display names
  const { data: teamMembers } = useCollection<any>('teamMembers', {
    where: [{ field: 'status', operator: '==', value: 'Active' }],
  });

  // Fetch user profiles for display names
  const { data: userProfiles } = useCollection<any>('userProfiles');

  const messageMutation = useMutation<ChatMessage>('messages');
  const notificationMutation = useMutation<any>('notifications');

  // Auto-scroll on new messages
  const prevCountRef = useRef(0);
  useEffect(() => {
    const count = messages?.length || 0;
    if (count > prevCountRef.current && scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
    prevCountRef.current = count;
  }, [messages?.length]);

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if ((!messageText.trim() && !attachmentUrl.trim()) || !user || !customerId) return;

    try {
      const msgContent = messageText || '≡ƒôÄ Bashk├½ngjitje';
      await messageMutation.create({
        content: msgContent,
        senderId: user.uid,
        channelId,
        isRead: false,
        attachmentUrl: attachmentUrl.trim() || undefined,
        senderType: 'client',
        ...(replyingTo ? {
          replyToId: replyingTo.id,
          replyToContent: replyingTo.content.slice(0, 100),
          replyToSender: getDisplayName(replyingTo.senderId),
        } : {}),
      } as any);

      // Notify team members ΓÇö works for BOTH general and project channels
      if (teamMembers) {
        let notifyMembers: any[] = [];
        if (selectedProjectId) {
          const project = customerProjects?.find(p => p.id === selectedProjectId);
          if (project?.teamId) {
            notifyMembers = teamMembers.filter(
              (m: any) => m.teamId === project.teamId && m.status === 'Active'
            );
          }
        }
        // For general channel or if no project team found, notify admins + CRM users
        if (notifyMembers.length === 0) {
          notifyMembers = teamMembers.filter(
            (m: any) => m.role === 'Admin' || m.canAccessCRM
          );
        }
        const channelLabel = selectedProjectId
          ? customerProjects?.find(p => p.id === selectedProjectId)?.name || 'Projekt'
          : 'Bised├½ e p├½rgjithshme';
        for (const member of notifyMembers) {
          try {
            await notificationMutation.create({
              userId: member.userId,
              type: 'client_message',
              title: `Mesazh i ri nga klienti - ${channelLabel}`,
              message: msgContent.length > 100 ? msgContent.slice(0, 100) + '...' : msgContent,
              isRead: false,
              linkTo: channelId,
            } as any);
          } catch { /* don't block */ }
        }
      }

      setMessageText('');
      setAttachmentUrl('');
      setShowAttachmentInput(false);
      setReplyingTo(null);
    } catch (err) {
      toast({
        title: 'Gabim',
        description: 'Mesazhi nuk u d├½rgua. Provoni p├½rs├½ri.',
        variant: 'destructive',
      });
    }
  };

  const getDisplayName = (senderId: string) => {
    if (senderId === user?.uid) return 'Ju';
    const profile = userProfiles?.find((p: any) => p.userId === senderId);
    if (profile?.displayName) return profile.displayName;
    const member = teamMembers?.find((m: any) => m.userId === senderId);
    if (member?.email) return member.email.split('@')[0];
    if (member) return `${member.role || 'Staf'}`;
    return 'Ekipi';
  };

  const getInitials = (senderId: string) => {
    const name = getDisplayName(senderId);
    return name.slice(0, 2).toUpperCase();
  };

  const getAvatarColor = (senderId: string) => {
    const colors = [
      'bg-blue-500', 'bg-emerald-500', 'bg-purple-500', 'bg-amber-500', 
      'bg-rose-500', 'bg-cyan-500', 'bg-indigo-500', 'bg-teal-500'
    ];
    let hash = 0;
    for (let i = 0; i < senderId.length; i++) hash = senderId.charCodeAt(i) + ((hash << 5) - hash);
    return colors[Math.abs(hash) % colors.length];
  };

  const isOwnMessage = (senderId: string) => senderId === user?.uid;

  // Toggle emoji reaction
  const handleReaction = async (msgId: string, emoji: string) => {
    if (!user) return;
    const msg = rawMessages?.find(m => m.id === msgId);
    if (!msg) return;
    const reactions = { ...((msg as any).reactions || {}) };
    const users = reactions[emoji] ? [...reactions[emoji]] : [];
    const idx = users.indexOf(user.uid);
    if (idx >= 0) users.splice(idx, 1);
    else users.push(user.uid);
    if (users.length === 0) delete reactions[emoji];
    else reactions[emoji] = users;
    try {
      await messageMutation.update(msgId, { reactions } as any);
    } catch { /* silent */ }
    setShowEmojiPicker(null);
  };

  // Group messages by date
  const formatDate = (date: any) => {
    if (!date) return '';
    const d = date instanceof Date ? date : date.toDate ? date.toDate() : new Date(date);
    if (isNaN(d.getTime())) return '';
    const now = new Date();
    const diffDays = Math.floor((now.getTime() - d.getTime()) / (1000 * 60 * 60 * 24));
    if (diffDays === 0) return 'Sot';
    if (diffDays === 1) return 'Dje';
    if (diffDays < 7) {
      const days = ['E Diel', 'E H├½n├½', 'E Mart├½', 'E M├½rkur├½', 'E Enjte', 'E Premte', 'E Shtun├½'];
      return days[d.getDay()];
    }
    return d.toLocaleDateString('sq-AL', { day: 'numeric', month: 'long', year: 'numeric' });
  };

  const formatTime = (date: any) => {
    if (!date) return '';
    const d = date instanceof Date ? date : date.toDate ? date.toDate() : new Date(date);
    if (isNaN(d.getTime())) return '';
    return d.toLocaleTimeString('sq-AL', { hour: '2-digit', minute: '2-digit' });
  };

  const getDateKey = (date: any) => {
    if (!date) return '';
    const d = date instanceof Date ? date : date.toDate ? date.toDate() : new Date(date);
    if (isNaN(d.getTime())) return '';
    return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
  };

  // Quick action messages
  const quickActions = [
    { icon: HelpCircle, label: 'Kam nj├½ pyetje', message: 'P├½rsh├½ndetje! Kam nj├½ pyetje p├½r ju.' },
    { icon: AlertCircle, label: 'Raportoj problem', message: 'P├½rsh├½ndetje, doja t├½ raportoja nj├½ problem.' },
    { icon: RefreshCw, label: 'K├½rkoj p├½rdit├½sim', message: 'P├½rsh├½ndetje, a mund t├½ m├½ jepni nj├½ p├½rdit├½sim mbi gjendjen e pun├½s?' },
  ];

  const sendQuickMessage = async (msg: string) => {
    if (!user || !customerId) return;
    try {
      await messageMutation.create({
        content: msg,
        senderId: user.uid,
        channelId,
        isRead: false,
        senderType: 'client',
      } as any);
    } catch {
      toast({ title: 'Gabim', description: 'Mesazhi nuk u d├½rgua.', variant: 'destructive' });
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-[60vh]">
        <div className="text-center space-y-3">
          <div className="w-12 h-12 border-4 border-primary/30 border-t-primary rounded-full animate-spin mx-auto" />
          <p className="text-muted-foreground text-sm">Duke ngarkuar bised├½n...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[calc(100dvh-140px)] sm:h-[calc(100dvh-160px)] max-w-3xl mx-auto">
      {/* Chat Header */}
      <div className="flex items-center gap-3 pb-3 sm:pb-4 border-b mb-0">
        <div className="relative">
          <div className="w-10 h-10 sm:w-11 sm:h-11 rounded-full bg-gradient-to-br from-primary to-primary/70 flex items-center justify-center text-primary-foreground font-bold text-sm">
            <MessageSquare className="h-5 w-5" />
          </div>
          <div className="absolute -bottom-0.5 -right-0.5 w-3.5 h-3.5 bg-emerald-500 rounded-full border-2 border-background" />
        </div>
        <div className="flex-1 min-w-0">
          <h1 className="font-semibold text-foreground text-base sm:text-lg">
            {selectedProjectId
              ? customerProjects?.find(p => p.id === selectedProjectId)?.name || 'Projekt'
              : 'Ekipi Yn├½'}
          </h1>
          <p className="text-xs text-emerald-600 font-medium">Aktiv tani</p>
        </div>
        {messages && messages.length > 0 && (
          <Badge variant="outline" className="text-xs hidden sm:flex">
            {messages.length} mesazhe
          </Badge>
        )}
      </div>

      {/* Project Tabs - Scrollable */}
      {customerProjects && customerProjects.length > 0 && (
        <div className="flex items-center gap-1.5 sm:gap-2 py-2 sm:py-3 border-b overflow-x-auto scrollbar-hide">
          <button
            className={`flex items-center gap-1.5 px-2.5 sm:px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap transition-all ${
              selectedProjectId === null
                ? 'bg-primary text-primary-foreground shadow-sm'
                : 'bg-muted text-muted-foreground hover:bg-accent'
            }`}
            onClick={() => setSelectedProjectId(null)}
          >
            <MessageSquare className="h-3 w-3" />
            P├½rgjithshme
          </button>
          {customerProjects.map((project) => (
            <button
              key={project.id}
              className={`flex items-center gap-1.5 px-2.5 sm:px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap transition-all ${
                selectedProjectId === project.id
                  ? 'bg-primary text-primary-foreground shadow-sm'
                  : 'bg-muted text-muted-foreground hover:bg-accent'
              }`}
              onClick={() => setSelectedProjectId(project.id)}
            >
              <FolderKanban className="h-3 w-3" />
              {project.name}
            </button>
          ))}
        </div>
      )}

      {/* Messages Area */}
      <div className="flex-1 overflow-hidden relative">
        <ScrollArea className="h-full">
          <div ref={scrollRef} className="px-2 py-4 space-y-1">
            {!messages || messages.length === 0 ? (
              /* Empty State - Personalized Welcome */
              <div className="flex flex-col items-center justify-center py-8 sm:py-12 px-4">
                <div className="w-16 h-16 sm:w-20 sm:h-20 rounded-full bg-gradient-to-br from-primary/20 to-primary/5 flex items-center justify-center mb-4 sm:mb-6">
                  <MessageSquare className="h-8 w-8 sm:h-10 sm:w-10 text-primary/60" />
                </div>
                <h2 className="text-lg sm:text-xl font-semibold text-foreground mb-2">
                  Mir├½ se vini! ≡ƒæï
                </h2>
                <p className="text-muted-foreground text-center text-sm mb-6 sm:mb-8 max-w-sm">
                  Jemi k├½tu p├½r t'ju ndihmuar. Zgjidhni nj├½ opsion m├½ posht├½ ose shkruani direkt mesazhin tuaj.
                </p>
                <div className="grid gap-3 w-full max-w-sm">
                  {quickActions.map((action, i) => {
                    const Icon = action.icon;
                    return (
                      <button
                        key={i}
                        onClick={() => sendQuickMessage(action.message)}
                        className="flex items-center gap-3 p-3 sm:p-3.5 rounded-xl border bg-card hover:bg-accent hover:border-primary/30 transition-all text-left group"
                      >
                        <div className="w-9 h-9 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0 group-hover:bg-primary/20 transition-colors">
                          <Icon className="h-4 w-4 text-primary" />
                        </div>
                        <span className="text-sm font-medium text-foreground">{action.label}</span>
                        <ChevronRight className="h-4 w-4 text-muted-foreground ml-auto group-hover:text-primary transition-colors" />
                      </button>
                    );
                  })}
                </div>
              </div>
            ) : (
              /* Messages with Date Separators */
              (() => {
                let lastDateKey = '';
                return messages.map((msg: any, idx: number) => {
                  const own = isOwnMessage(msg.senderId);
                  const dateKey = getDateKey(msg.createdAt);
                  const showDateSeparator = dateKey !== lastDateKey;
                  lastDateKey = dateKey;
                  const prevMsg = idx > 0 ? messages[idx - 1] : null;
                  const sameSenderAsPrev = prevMsg && prevMsg.senderId === msg.senderId && !showDateSeparator;

                  return (
                    <React.Fragment key={msg.id}>
                      {showDateSeparator && (
                        <div className="flex items-center justify-center py-4">
                          <div className="px-3 py-1 rounded-full bg-muted text-muted-foreground text-[11px] font-medium shadow-sm">
                            {formatDate(msg.createdAt)}
                          </div>
                        </div>
                      )}
                      <div
                        className={`flex group ${own ? 'justify-end' : 'justify-start'} ${sameSenderAsPrev ? 'mt-0.5' : 'mt-3'}`}
                      >
                        {/* Team Avatar */}
                        {!own && (
                          <div className="flex-shrink-0 mr-2 self-end">
                            {!sameSenderAsPrev ? (
                              <div className={`w-7 h-7 sm:w-8 sm:h-8 rounded-full ${getAvatarColor(msg.senderId)} flex items-center justify-center text-white text-xs font-bold shadow-sm`}>
                                {getInitials(msg.senderId)}
                              </div>
                            ) : (
                              <div className="w-7 sm:w-8" />
                            )}
                          </div>
                        )}

                        <div className={`max-w-[82%] sm:max-w-[78%] ${own ? 'items-end' : 'items-start'} flex flex-col`}>
                          {/* Sender name for team messages */}
                          {!own && !sameSenderAsPrev && (
                            <span className="text-[11px] font-medium text-muted-foreground mb-1 ml-1">
                              {getDisplayName(msg.senderId)}
                              {msg.senderType === 'staff' && (
                                <Badge variant="outline" className="h-3.5 px-1 text-[8px] ml-1 border-blue-300 text-blue-600 inline-flex">Staf</Badge>
                              )}
                            </span>
                          )}

                          {/* Reply preview */}
                          {msg.replyToContent && (
                            <div className="text-[11px] mb-1 p-1.5 rounded border-l-2 bg-muted/40 border-primary/40 max-w-full">
                              <span className="font-medium">{msg.replyToSender}</span>
                              <p className="truncate opacity-80">{msg.replyToContent}</p>
                            </div>
                          )}

                          <div
                            className={`rounded-2xl px-3 sm:px-3.5 py-2 relative ${
                              own
                                ? 'bg-primary text-primary-foreground rounded-br-sm'
                                : 'bg-muted/80 border border-border/50 rounded-bl-sm'
                            }`}
                          >
                            <p className="text-[13px] sm:text-[13.5px] leading-relaxed whitespace-pre-wrap break-words">{msg.content}</p>
                            {msg.attachmentUrl && (
                              <a
                                href={msg.attachmentUrl}
                                target="_blank"
                                rel="noopener noreferrer"
                                className={`inline-flex items-center gap-1.5 text-xs mt-1.5 px-2 py-1 rounded-md ${
                                  own ? 'bg-primary-foreground/15 text-primary-foreground hover:bg-primary-foreground/25' : 'bg-background text-primary hover:bg-accent'
                                } transition-colors`}
                              >
                                <FileIcon className="h-3 w-3" />
                                Skedar i bashk├½ngjitur
                              </a>
                            )}

                            {/* Message actions on hover */}
                            <div className={`absolute -top-3 ${own ? 'left-1' : 'right-1'} opacity-0 group-hover:opacity-100 transition-opacity flex items-center gap-0.5 bg-background border rounded-lg shadow-sm px-1 py-0.5 z-10`}>
                              <div className="relative">
                                <button
                                  className="p-1 hover:bg-accent rounded text-muted-foreground hover:text-foreground"
                                  onClick={() => setShowEmojiPicker(showEmojiPicker === msg.id ? null : msg.id)}
                                >
                                  <SmilePlus className="h-3.5 w-3.5" />
                                </button>
                                {showEmojiPicker === msg.id && (
                                  <div className={`absolute bottom-full ${own ? 'left-0' : 'right-0'} mb-1 flex gap-1 bg-popover border rounded-lg shadow-lg p-1.5 z-50`}>
                                    {EMOJI_REACTIONS.map(emoji => (
                                      <button
                                        key={emoji}
                                        onClick={() => handleReaction(msg.id, emoji)}
                                        className="hover:bg-accent rounded p-1 text-base transition-transform hover:scale-125"
                                      >
                                        {emoji}
                                      </button>
                                    ))}
                                  </div>
                                )}
                              </div>
                              <button
                                className="p-1 hover:bg-accent rounded text-muted-foreground hover:text-foreground"
                                onClick={() => setReplyingTo(msg)}
                              >
                                <Reply className="h-3.5 w-3.5" />
                              </button>
                            </div>
                          </div>

                          {/* Reactions display */}
                          {msg.reactions && Object.keys(msg.reactions).length > 0 && (
                            <div className="flex flex-wrap gap-1 mt-1">
                              {Object.entries(msg.reactions as Record<string, string[]>).map(([emoji, users]) => (
                                <button
                                  key={emoji}
                                  onClick={() => handleReaction(msg.id, emoji)}
                                  className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full text-xs border transition-colors ${
                                    users.includes(user?.uid || '')
                                      ? 'bg-primary/10 border-primary/30'
                                      : 'bg-muted border-border hover:bg-accent'
                                  }`}
                                >
                                  {emoji} <span className="text-[10px]">{users.length}</span>
                                </button>
                              ))}
                            </div>
                          )}

                          {/* Timestamp */}
                          <span className={`text-[10px] mt-0.5 px-1.5 ${own ? 'text-muted-foreground/60' : 'text-muted-foreground/60'}`}>
                            {formatTime(msg.createdAt)}
                            {msg.editedAt && ' ┬╖ ndryshuar'}
                            {own && (
                              <span className="ml-1 text-primary/60">Γ£ô</span>
                            )}
                          </span>
                        </div>
                      </div>
                    </React.Fragment>
                  );
                });
              })()
            )}
          </div>
        </ScrollArea>
      </div>

      {/* Reply preview */}
      {replyingTo && (
        <div className="flex items-center gap-2 px-2 py-1.5 bg-muted/60 border-l-2 border-primary rounded-lg mx-1 mb-1">
          <Reply className="h-4 w-4 text-primary flex-shrink-0" />
          <div className="flex-1 min-w-0">
            <span className="text-xs font-medium text-primary">{getDisplayName(replyingTo.senderId)}</span>
            <p className="text-xs text-muted-foreground truncate">{replyingTo.content}</p>
          </div>
          <Button variant="ghost" size="icon" className="h-6 w-6 flex-shrink-0" onClick={() => setReplyingTo(null)}>
            <X className="h-3 w-3" />
          </Button>
        </div>
      )}

      {/* Message Input Area */}
      <div className="border-t bg-background pt-2 pb-1">
        {showAttachmentInput && (
          <div className="flex items-center gap-2 mb-2 px-1">
            <div className="flex-1 flex items-center gap-2 bg-muted rounded-lg px-3 py-2">
              <Paperclip className="h-4 w-4 text-muted-foreground flex-shrink-0" />
              <Input
                placeholder="Ngjitni linkun e skedarit..."
                value={attachmentUrl}
                onChange={(e) => setAttachmentUrl(e.target.value)}
                className="border-0 bg-transparent h-auto p-0 focus-visible:ring-0 text-sm min-w-0"
              />
            </div>
            <Button variant="ghost" size="icon" className="h-8 w-8 flex-shrink-0" onClick={() => { setShowAttachmentInput(false); setAttachmentUrl(''); }}>
              <X className="h-4 w-4" />
            </Button>
          </div>
        )}
        <form onSubmit={handleSendMessage} className="flex items-end gap-1.5 sm:gap-2">
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="h-9 w-9 sm:h-10 sm:w-10 rounded-full flex-shrink-0 text-muted-foreground hover:text-foreground"
            onClick={() => setShowAttachmentInput(!showAttachmentInput)}
          >
            <Paperclip className="h-4 w-4 sm:h-5 sm:w-5" />
          </Button>
          <div className="flex-1 min-w-0">
            <Input
              placeholder="Shkruani mesazhin..."
              value={messageText}
              onChange={(e) => setMessageText(e.target.value)}
              className="rounded-full pr-4 h-9 sm:h-10 bg-muted/50 border-muted-foreground/20 focus:bg-background transition-colors"
            />
          </div>
          <Button 
            type="submit" 
            size="icon" 
            disabled={!messageText.trim() && !attachmentUrl.trim()} 
            className="h-9 w-9 sm:h-10 sm:w-10 rounded-full flex-shrink-0 shadow-sm"
          >
            <Send className="h-4 w-4" />
          </Button>
        </form>
      </div>
    </div>
  );
};

export default PortalChatView;

import React, { useState, useEffect } from 'react';
import { useClientPortal } from '../../hooks/useClientPortal';
import { useCollection, useMutation } from '../../hooks/useFirestore';
import { useAuth } from '../../contexts/AuthContext';
import { Card, CardContent } from '../../components/ui/card';
import { Badge } from '../../components/ui/badge';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../../components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '../../components/ui/dialog';
import { Separator } from '../../components/ui/separator';
import { FileText, Search, Eye, DollarSign, Calendar, CreditCard, Check, ExternalLink } from 'lucide-react';
import { useToast } from '../../hooks/use-toast';
import type { Invoice, InvoiceItem, Service, Customer } from '../../types';

const PortalInvoicesView: React.FC = () => {
  const { customerId } = useClientPortal();
  const { user } = useAuth();
  const { toast } = useToast();
  const [statusFilter, setStatusFilter] = useState<string>('__all__');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);

  // Handle Stripe redirect params
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const payment = params.get('payment');
    if (payment === 'success') {
      toast({ title: 'Pagesa u krye me sukses!' });
      window.history.replaceState({}, '', window.location.pathname);
    } else if (payment === 'cancelled') {
      toast({ title: 'Pagesa u anulua', variant: 'destructive' });
      window.history.replaceState({}, '', window.location.pathname);
    }
  }, []);

  const { data: rawInvoices, loading } = useCollection<Invoice>('invoices', {
    where: [{ field: 'customerId', operator: '==', value: customerId || '' }],
    skipTeamFilter: true,
  });

  // Sort client-side (avoids Firestore composite index requirement)
  const invoices = React.useMemo(() => {
    if (!rawInvoices) return [];
    return [...rawInvoices].sort((a, b) => {
      const ta = a.createdAt instanceof Date ? a.createdAt.getTime() : (a.createdAt as any)?.toMillis?.() ?? 0;
      const tb = b.createdAt instanceof Date ? b.createdAt.getTime() : (b.createdAt as any)?.toMillis?.() ?? 0;
      return tb - ta;
    });
  }, [rawInvoices]);

  const { data: invoiceItems } = useCollection<InvoiceItem>('invoiceItems', { skipTeamFilter: true });
  const { data: services } = useCollection<Service>('services', { skipTeamFilter: true });
  const { data: customers } = useCollection<Customer>('customers', { skipTeamFilter: true });
  useMutation<Invoice>('invoices');

  const customer = customers?.find(c => c.id === customerId);

  const handleStripePayment = async (invoice: Invoice) => {
    const stripeKey = import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY;
    
    if (!stripeKey) {
      toast({
        title: 'Pagesa nuk ├½sht├½ e disponueshme',
        description: 'Kontaktoni ekipin p├½r t├½ marr├½ linkun e pages├½s.',
        variant: 'destructive',
      });
      return;
    }

    const amount = invoice.total ?? invoice.amount ?? 0;
    if (amount <= 0) {
      toast({ title: 'Shuma e fatur├½s ├½sht├½ 0', variant: 'destructive' });
      return;
    }

    try {
      toast({ title: 'Duke hapur Stripe Checkout...' });
      const authToken = await user?.getIdToken();
      const response = await fetch('/api/create-checkout-session', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(authToken ? { 'Authorization': `Bearer ${authToken}` } : {}),
        },
        body: JSON.stringify({
          invoiceId: invoice.id,
          invoiceNumber: invoice.invoiceNumber || invoice.id.slice(0, 8),
          amount,
          currency: 'eur',
          customerEmail: customer?.email || undefined,
          customerName: customer?.name || undefined,
          successUrl: `${window.location.origin}/portal/invoices?payment=success`,
          cancelUrl: `${window.location.origin}/portal/invoices?payment=cancelled`,
        }),
      });

      if (!response.ok) throw new Error('Gabim gjat├½ krijimit t├½ sesionit');
      const { url } = await response.json();
      if (url) {
        try {
          const parsed = new URL(url);
          if (parsed.hostname.endsWith('.stripe.com') || parsed.hostname === 'stripe.com') {
            window.location.href = url;
          } else {
            throw new Error('URL e pages├½s nuk ├½sht├½ e vlefshme');
          }
        } catch {
          throw new Error('URL e pages├½s nuk ├½sht├½ e vlefshme');
        }
      }
    } catch (err: any) {
      toast({ title: 'Gabim me Stripe', description: err.message, variant: 'destructive' });
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Paid': return 'bg-green-100 text-green-800';
      case 'Pending': return 'bg-yellow-100 text-yellow-800';
      case 'Overdue': return 'bg-red-100 text-red-800';
      case 'Draft': return 'bg-gray-100 text-gray-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case 'Paid': return 'E Paguar';
      case 'Pending': return 'N├½ Pritje';
      case 'Overdue': return 'E Vonuar';
      case 'Draft': return 'Skic├½';
      default: return status;
    }
  };

  const filteredInvoices = React.useMemo(() => {
    if (!invoices) return [];
    return invoices.filter(inv => {
      if (statusFilter !== '__all__' && inv.status !== statusFilter) return false;
      if (searchQuery) {
        const q = searchQuery.toLowerCase();
        const num = inv.invoiceNumber || `INV-${inv.id.slice(0, 6)}`;
        if (!num.toLowerCase().includes(q)) return false;
      }
      return true;
    });
  }, [invoices, statusFilter, searchQuery]);

  const selectedItems = invoiceItems?.filter(item => item.invoiceId === selectedInvoice?.id) || [];

  const getServiceName = (serviceId?: string) => {
    if (!serviceId) return 'Sh├½rbim';
    const service = services?.find(s => s.id === serviceId);
    return service?.title || service?.name || 'Sh├½rbim';
  };

  const totalPaid = invoices?.filter(i => i.status === 'Paid').reduce((s, i) => s + (i.total ?? i.amount ?? 0), 0) || 0;
  const totalPending = invoices?.filter(i => i.status === 'Pending' || i.status === 'Overdue').reduce((s, i) => s + (i.total ?? i.amount ?? 0), 0) || 0;

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-muted-foreground">Duke ngarkuar faturat...</div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Faturat</h1>
        <p className="text-muted-foreground mt-1">
          Shikoni dhe menaxhoni faturat tuaja
        </p>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-green-100 rounded-lg">
                <DollarSign className="h-5 w-5 text-green-600" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">E Paguar</p>
                <p className="text-xl font-bold">{totalPaid.toLocaleString()} ALL</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-yellow-100 rounded-lg">
                <CreditCard className="h-5 w-5 text-yellow-600" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">N├½ Pritje</p>
                <p className="text-xl font-bold">{totalPending.toLocaleString()} ALL</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-blue-100 rounded-lg">
                <FileText className="h-5 w-5 text-blue-600" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">Totale Fatura</p>
                <p className="text-xl font-bold">{invoices?.length || 0}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="K├½rko fatur├½..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10"
          />
        </div>
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-full sm:w-[180px]">
            <SelectValue placeholder="Statusi" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="__all__">T├½ gjitha</SelectItem>
            <SelectItem value="Paid">E Paguar</SelectItem>
            <SelectItem value="Pending">N├½ Pritje</SelectItem>
            <SelectItem value="Overdue">E Vonuar</SelectItem>
            <SelectItem value="Draft">Skic├½</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Invoices List */}
      {filteredInvoices.length === 0 ? (
        <Card>
          <CardContent className="py-12 text-center">
            <FileText className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
            <p className="text-muted-foreground">Nuk u gjet asnj├½ fatur├½</p>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-3">
          {filteredInvoices.map(invoice => (
            <Card key={invoice.id} className="hover:shadow-md transition-shadow">
              <CardContent className="py-4">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                  <div className="flex items-center gap-4">
                    <div className="p-2 bg-muted rounded-lg">
                      <FileText className="h-5 w-5 text-muted-foreground" />
                    </div>
                    <div>
                      <p className="font-semibold">
                        {invoice.invoiceNumber || `INV-${invoice.id.slice(0, 6)}`}
                      </p>
                      <div className="flex items-center gap-2 text-sm text-muted-foreground mt-0.5">
                        <Calendar className="h-3.5 w-3.5" />
                        {invoice.createdAt instanceof Date
                          ? invoice.createdAt.toLocaleDateString('sq-AL')
                          : ''}
                        {invoice.dueDate && (
                          <>
                            <span>ΓÇó</span>
                            <span>
                              Afati: {invoice.dueDate instanceof Date
                                ? invoice.dueDate.toLocaleDateString('sq-AL')
                                : ''}
                            </span>
                          </>
                        )}
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-3">
                    <span className="text-lg font-bold">
                      {(invoice.total || invoice.amount || 0).toLocaleString()} ALL
                    </span>
                    <Badge className={getStatusColor(invoice.status)} variant="secondary">
                      {getStatusLabel(invoice.status)}
                    </Badge>
                    {(invoice.status === 'Pending' || invoice.status === 'Overdue') && (
                      <Button
                        size="sm"
                        className="bg-[#635BFF] hover:bg-[#5851ea] text-white"
                        onClick={() => handleStripePayment(invoice)}
                      >
                        <CreditCard className="w-4 h-4 mr-1" />
                        Paguaj
                      </Button>
                    )}
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => setSelectedInvoice(invoice)}
                    >
                      <Eye className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Invoice Detail Dialog */}
      <Dialog open={!!selectedInvoice} onOpenChange={(open) => !open && setSelectedInvoice(null)}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>
              Fatura {selectedInvoice?.invoiceNumber || `INV-${selectedInvoice?.id?.slice(0, 6)}`}
            </DialogTitle>
          </DialogHeader>
          {selectedInvoice && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <p className="text-muted-foreground">Data</p>
                  <p className="font-medium">
                    {selectedInvoice.createdAt instanceof Date
                      ? selectedInvoice.createdAt.toLocaleDateString('sq-AL')
                      : '-'}
                  </p>
                </div>
                <div>
                  <p className="text-muted-foreground">Afati</p>
                  <p className="font-medium">
                    {selectedInvoice.dueDate instanceof Date
                      ? selectedInvoice.dueDate.toLocaleDateString('sq-AL')
                      : '-'}
                  </p>
                </div>
                <div>
                  <p className="text-muted-foreground">Statusi</p>
                  <Badge className={getStatusColor(selectedInvoice.status)} variant="secondary">
                    {getStatusLabel(selectedInvoice.status)}
                  </Badge>
                </div>
                <div>
                  <p className="text-muted-foreground">M├½nyra e Pages├½s</p>
                  <p className="font-medium">{selectedInvoice.paymentMethod || '-'}</p>
                </div>
              </div>

              {customer && (
                <>
                  <Separator />
                  <div className="text-sm">
                    <p className="text-muted-foreground mb-1">Klienti</p>
                    <p className="font-medium">{customer.name}</p>
                    {customer.company && <p className="text-muted-foreground">{customer.company}</p>}
                    {customer.email && <p className="text-muted-foreground">{customer.email}</p>}
                  </div>
                </>
              )}

              {selectedItems.length > 0 && (
                <>
                  <Separator />
                  <div>
                    <p className="text-sm text-muted-foreground mb-2">Artikujt</p>
                    <div className="space-y-2">
                      {selectedItems.map(item => (
                        <div key={item.id} className="flex items-center justify-between text-sm py-1.5 border-b last:border-0">
                          <div>
                            <p className="font-medium">{item.description || getServiceName(item.serviceId)}</p>
                            <p className="text-muted-foreground">
                              {item.quantity} ├ù {item.unitPrice.toLocaleString()} ALL
                            </p>
                          </div>
                          <p className="font-semibold">{item.totalPrice.toLocaleString()} ALL</p>
                        </div>
                      ))}
                    </div>
                  </div>
                </>
              )}

              <Separator />
              <div className="flex items-center justify-between text-lg font-bold">
                <span>Totali</span>
                <span>{(selectedInvoice.total || selectedInvoice.amount || 0).toLocaleString()} ALL</span>
              </div>

              {/* Stripe Payment Section */}
              {(selectedInvoice.status === 'Pending' || selectedInvoice.status === 'Overdue') && (
                <div className="space-y-2 pt-2">
                  {(selectedInvoice as any).paymentUrl && (
                    <Button asChild className="w-full" variant="outline">
                      <a href={(selectedInvoice as any).paymentUrl} target="_blank" rel="noopener noreferrer">
                        <ExternalLink className="w-4 h-4 mr-2" />
                        Hap Linkun e Pages├½s
                      </a>
                    </Button>
                  )}
                  <Button
                    className="w-full bg-[#635BFF] hover:bg-[#5851ea] text-white"
                    onClick={() => handleStripePayment(selectedInvoice)}
                  >
                    <CreditCard className="w-4 h-4 mr-2" />
                    Paguaj me Stripe
                  </Button>
                </div>
              )}

              {selectedInvoice.status === 'Paid' && (
                <div className="flex items-center justify-center gap-2 p-3 bg-green-50 border border-green-200 rounded-lg text-green-700">
                  <Check className="w-5 h-5" />
                  <span className="font-medium">Fatura ├½sht├½ e paguar</span>
                </div>
              )}
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default PortalInvoicesView;

import React, { useState, useCallback } from 'react';
import { useClientPortal } from '../../hooks/useClientPortal';
import { useAuth } from '../../contexts/AuthContext';
import { useCollection, useMutation } from '../../hooks/useFirestore';
import { Card, CardContent } from '../../components/ui/card';
import { Badge } from '../../components/ui/badge';
import { Button } from '../../components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '../../components/ui/dialog';
import { ShoppingBag, Tag, DollarSign, FileText, CheckCircle2, Clock, Eye, Edit3, Send } from 'lucide-react';
import { useToast } from '../../hooks/use-toast';
import ServiceQuestionnaireForm from '../../components/ServiceQuestionnaireForm';
import type { Invoice, InvoiceItem, Service, ServiceInquiry, Lead, Customer, Task, Notification } from '../../types';

const PortalServicesView: React.FC = () => {
  const { user } = useAuth();
  const { customerId } = useClientPortal();
  const { toast } = useToast();
  const [isQuestionnaireOpen, setIsQuestionnaireOpen] = useState(false);
  const [preselectedService, setPreselectedService] = useState<string | undefined>();
  const [showSuccess, setShowSuccess] = useState(false);
  const [editingInquiry, setEditingInquiry] = useState<ServiceInquiry | null>(null);
  const [viewingInquiry, setViewingInquiry] = useState<ServiceInquiry | null>(null);

  const { data: invoices } = useCollection<Invoice>('invoices', {
    where: [{ field: 'customerId', operator: '==', value: customerId || '' }],
    skipTeamFilter: true,
  });

  const { data: invoiceItems } = useCollection<InvoiceItem>('invoiceItems', { skipTeamFilter: true });
  const { data: services, loading } = useCollection<Service>('services', { skipTeamFilter: true });

  // Fetch client's own inquiries
  const { data: myInquiries } = useCollection<ServiceInquiry>('serviceInquiries', {
    where: user?.uid ? [{ field: 'clientUserId', operator: '==', value: user.uid }] : [],
    orderBy: { field: 'createdAt', direction: 'desc' },
    skipTeamFilter: true,
  });

  // Mutations for CRM automation
  const inquiryMutation = useMutation<ServiceInquiry>('serviceInquiries');
  const leadMutation = useMutation<Lead>('leads');
  useMutation<Customer>('customers');
  const taskMutation = useMutation<Task>('tasks');
  const notificationMutation = useMutation<Notification>('notifications');
  const { data: activeTeamMembers } = useCollection<any>('teamMembers', {
    where: [{ field: 'status', operator: '==', value: 'Active' }]
  });

  // Handle questionnaire submission with CRM automations
  const handleQuestionnaireSubmit = async (formData: any) => {
    // If editing an existing inquiry, update it
    if (editingInquiry) {
      await inquiryMutation.update(editingInquiry.id, {
        ...formData,
        status: editingInquiry.status === 'Draft' ? 'New' : editingInquiry.status,
        isDraft: false,
        clientUserId: user?.uid || undefined,
      });

      // If it was a draft being submitted for the first time, create Lead + Task + Notifications
      if (editingInquiry.status === 'Draft') {
        await createLeadAndAutomations(formData, editingInquiry.id);
      }

      setEditingInquiry(null);
      setIsQuestionnaireOpen(false);
      setShowSuccess(true);
      toast({
        title: editingInquiry.status === 'Draft' ? 'K├½rkesa u d├½rgua me sukses!' : 'K├½rkesa u p├½rdit├½sua!',
        description: 'Ekipi yn├½ do t\'ju kontaktoj├½ s├½ shpejti.',
      });
      return;
    }

    // 1. Save inquiry to Firestore
    const inquiry = await inquiryMutation.create({
      ...formData,
      status: 'New',
      isDraft: false,
      customerId: customerId || undefined,
      clientUserId: user?.uid || undefined,
    });

    await createLeadAndAutomations(formData, inquiry.id);

    setIsQuestionnaireOpen(false);
    setShowSuccess(true);
    toast({
      title: 'Formulari u d├½rgua me sukses!',
      description: 'Ekipi yn├½ do t\'ju kontaktoj├½ s├½ shpejti.',
    });
  };

  // Draft auto-save handler
  const handleDraftSave = useCallback(async (formData: any, step: number) => {
    if (editingInquiry?.status === 'Draft') {
      // Update existing draft
      await inquiryMutation.update(editingInquiry.id, {
        ...formData,
        lastSavedStep: step,
        isDraft: true,
        status: 'Draft',
      });
    }
  }, [editingInquiry, inquiryMutation]);

  const createLeadAndAutomations = async (formData: any, inquiryId: string) => {

    // 2. Determine tags
    const tags: string[] = [];
    if (formData.servicesInterestedIn.includes('Web Design')) tags.push('Web Design Lead');
    if (formData.servicesInterestedIn.includes('Social Media Marketing')) tags.push('SMM Lead');
    if (formData.servicesInterestedIn.includes('Paid Ads')) tags.push('Ads Lead');
    if (['100,000ΓÇô300,000 L', '300,000+ L'].includes(formData.budgetRange)) tags.push('High Value Lead');
    if (formData.timeline === 'Menj├½her├½') tags.push('Urgent Lead');

    // 3. Estimate value from budget range
    let estimatedValue = 0;
    if (formData.budgetRange === 'N├½n 30,000 L') estimatedValue = 20000;
    else if (formData.budgetRange === '30,000ΓÇô50,000 L') estimatedValue = 40000;
    else if (formData.budgetRange === '50,000ΓÇô100,000 L') estimatedValue = 75000;
    else if (formData.budgetRange === '100,000ΓÇô300,000 L') estimatedValue = 200000;
    else if (formData.budgetRange === '300,000+ L') estimatedValue = 400000;

    // 4. Create Lead in CRM
    const lead = await leadMutation.create({
      name: formData.contactName,
      email: formData.email,
      phoneNumber: formData.phoneNumber,
      company: formData.businessName,
      jobTitle: formData.jobTitle || undefined,
      website: formData.website || undefined,
      status: 'New',
      source: 'Service Questionnaire',
      estimatedValue,
      tags,
      notes: `Sh├½rbime: ${formData.servicesInterestedIn.join(', ')}\nObjektivi: ${formData.mainGoal}\nBuxheti: ${formData.budgetRange}\nAfati: ${formData.timeline}\n\nP├½rshkrimi: ${formData.projectNeedDescription}\nSfida: ${formData.currentMainChallenge}`,
      serviceInquiryId: inquiryId,
    });

    // 5. Update inquiry with leadId
    await inquiryMutation.update(inquiryId, { leadId: lead.id });

    // 6. Create task: "Kontakto lead-in brenda 24 or├½ve"
    const taskPriority = formData.timeline === 'Menj├½her├½' || formData.isUrgent === 'Po' ? 'urgent' : 'high';
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    const salesAdminMembers = activeTeamMembers?.filter((m: any) => m.role === 'Admin' || m.canAccessCRM) || [];
    
    await taskMutation.create({
      title: `Kontakto lead: ${formData.contactName} (${formData.businessName})`,
      description: `Lead i ri nga pyet├½sori i sh├½rbimeve.\n\nSh├½rbime: ${formData.servicesInterestedIn.join(', ')}\nObjektivi: ${formData.mainGoal}\nBuxheti: ${formData.budgetRange}\nAfati: ${formData.timeline}\nKontakt: ${formData.email} / ${formData.phoneNumber}${formData.preferredContactMethod ? '\nM├½nyra e preferuar: ' + formData.preferredContactMethod : ''}`,
      status: 'Todo',
      priority: taskPriority,
      startDate: new Date(),
      endDate: tomorrow,
      dueDate: tomorrow,
      assignedToUserId: salesAdminMembers?.[0]?.userId || '',
    });

    // 7. Send notification to Admin + Sales (canAccessCRM) team members
    if (salesAdminMembers.length > 0) {
      await Promise.all(
        salesAdminMembers.map((m: any) => notificationMutation.create({
          userId: m.userId,
          type: 'lead_created',
          title: 'Lead i Ri nga Pyet├½sori',
          message: `${formData.contactName} (${formData.businessName}) dor├½zoi pyet├½sorin p├½r: ${formData.servicesInterestedIn.join(', ')}`,
          isRead: false,
        }))
      );
    }

  };

  const openQuestionnaire = (serviceCategory?: string) => {
    setPreselectedService(serviceCategory);
    setShowSuccess(false);
    setEditingInquiry(null);
    setIsQuestionnaireOpen(true);
  };

  const openEditInquiry = (inquiry: ServiceInquiry) => {
    setEditingInquiry(inquiry);
    setPreselectedService(undefined);
    setShowSuccess(false);
    setIsQuestionnaireOpen(true);
  };

  const openViewInquiry = (inquiry: ServiceInquiry) => {
    setViewingInquiry(inquiry);
  };

  const startNewDraft = async (serviceCategory?: string) => {
    const draft = await inquiryMutation.create({
      businessName: '',
      contactName: user?.displayName || '',
      email: user?.email || '',
      status: 'Draft',
      isDraft: true,
      clientUserId: user?.uid || undefined,
      customerId: customerId || undefined,
      servicesInterestedIn: serviceCategory ? [serviceCategory] : [],
      lastSavedStep: 1,
    } as any);
    setEditingInquiry({ ...draft, id: draft.id } as any);
    setPreselectedService(serviceCategory);
    setShowSuccess(false);
    setIsQuestionnaireOpen(true);
  };

  // Build a map of purchased services from invoice items
  const purchasedServiceDetails = React.useMemo(() => {
    if (!invoices || !invoiceItems || !services) return [];

    const invoiceIds = new Set(invoices.map(i => i.id));
    const myItems = invoiceItems.filter(item => invoiceIds.has(item.invoiceId));

    // Group by service
    const serviceMap = new Map<string, { service: Service; totalSpent: number; invoiceCount: number; lastPurchase: Date | null }>();

    myItems.forEach(item => {
      if (!item.serviceId) return;
      const service = services.find(s => s.id === item.serviceId);
      if (!service) return;

      const existing = serviceMap.get(service.id);
      const invoice = invoices.find(i => i.id === item.invoiceId);
      const invoiceDate = invoice?.createdAt instanceof Date ? invoice.createdAt : null;

      if (existing) {
        existing.totalSpent += item.totalPrice;
        existing.invoiceCount += 1;
        if (invoiceDate && (!existing.lastPurchase || invoiceDate > existing.lastPurchase)) {
          existing.lastPurchase = invoiceDate;
        }
      } else {
        serviceMap.set(service.id, {
          service,
          totalSpent: item.totalPrice,
          invoiceCount: 1,
          lastPurchase: invoiceDate,
        });
      }
    });

    return Array.from(serviceMap.values()).sort((a, b) => b.totalSpent - a.totalSpent);
  }, [invoices, invoiceItems, services]);

  // All available services (for browsing)
  const allServices = services || [];

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-muted-foreground">Duke ngarkuar sh├½rbimet...</div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Sh├½rbimet</h1>
          <p className="text-muted-foreground mt-1">
            Sh├½rbimet tuaja t├½ blera dhe katalogu i sh├½rbimeve
          </p>
        </div>
        <Button onClick={() => openQuestionnaire()} className="gap-2">
          <FileText className="w-4 h-4" />
          K├½rko Sh├½rbim
        </Button>
      </div>

      {/* Success message if just submitted */}
      {showSuccess && (
        <Card className="border-green-200 bg-green-50 dark:bg-green-950/20 dark:border-green-800/40">
          <CardContent className="py-6 flex items-center gap-4">
            <CheckCircle2 className="w-8 h-8 text-green-600 flex-shrink-0" />
            <div>
              <h3 className="font-semibold text-green-800 dark:text-green-300">Formulari u d├½rgua me sukses!</h3>
              <p className="text-sm text-green-700 dark:text-green-400 mt-1">
                Ekipi yn├½ do t├½ shqyrtoj├½ k├½rkes├½n tuaj dhe do t'ju kontaktoj├½ brenda 24 or├½ve.
              </p>
            </div>
          </CardContent>
        </Card>
      )}

      {/* My Inquiries */}
      {myInquiries && myInquiries.length > 0 && (
        <div>
          <h2 className="text-lg font-semibold mb-4">K├½rkesat e Mia</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {myInquiries.map(inquiry => {
              const statusConfig: Record<string, { label: string; color: string }> = {
                'Draft': { label: 'Draft', color: 'bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300' },
                'New': { label: 'D├½rguar', color: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300' },
                'Reviewed': { label: 'N├½ Shqyrtim', color: 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300' },
                'Converted': { label: 'Konvertuar', color: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300' },
              };
              const status = statusConfig[inquiry.status] || statusConfig['New'];
              const createdDate = inquiry.createdAt instanceof Date
                ? inquiry.createdAt.toLocaleDateString('sq-AL')
                : '';
              return (
                <Card key={inquiry.id} className="hover:shadow-md transition-shadow">
                  <CardContent className="pt-6">
                    <div className="flex items-start justify-between gap-2">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          <h3 className="font-semibold truncate">{inquiry.businessName || 'K├½rkes├½ pa titull'}</h3>
                          <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${status.color}`}>{status.label}</span>
                        </div>
                        {inquiry.servicesInterestedIn && inquiry.servicesInterestedIn.length > 0 && (
                          <div className="flex flex-wrap gap-1 mb-2">
                            {inquiry.servicesInterestedIn.map(s => (
                              <Badge key={s} variant="secondary" className="text-xs">{s}</Badge>
                            ))}
                          </div>
                        )}
                        <p className="text-xs text-muted-foreground">
                          {createdDate}
                          {inquiry.budgetRange && ` ┬╖ ${inquiry.budgetRange}`}
                        </p>
                      </div>
                    </div>
                    <div className="flex gap-2 mt-3">
                      {inquiry.status === 'Draft' ? (
                        <Button size="sm" className="gap-1 flex-1" onClick={() => openEditInquiry(inquiry)}>
                          <Send className="w-3.5 h-3.5" />
                          Vazhdo & D├½rgo
                        </Button>
                      ) : (
                        <>
                          <Button size="sm" variant="outline" className="gap-1 flex-1" onClick={() => openViewInquiry(inquiry)}>
                            <Eye className="w-3.5 h-3.5" />
                            Shiko
                          </Button>
                          {inquiry.status === 'New' && (
                            <Button size="sm" variant="outline" className="gap-1" onClick={() => openEditInquiry(inquiry)}>
                              <Edit3 className="w-3.5 h-3.5" />
                              Edito
                            </Button>
                          )}
                        </>
                      )}
                    </div>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        </div>
      )}

      {/* Purchased Services */}
      <div>
        <h2 className="text-lg font-semibold mb-4">Sh├½rbimet e Blera</h2>
        {purchasedServiceDetails.length === 0 ? (
          <Card>
            <CardContent className="py-12 text-center">
              <ShoppingBag className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
              <p className="text-muted-foreground">Nuk keni bler├½ asnj├½ sh├½rbim akoma</p>
            </CardContent>
          </Card>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {purchasedServiceDetails.map(({ service, totalSpent, invoiceCount, lastPurchase }) => (
              <Card key={service.id} className="hover:shadow-md transition-shadow">
                <CardContent className="pt-6">
                  <div className="flex items-start gap-4">
                    <div className="p-2.5 bg-primary/10 rounded-lg flex-shrink-0">
                      <ShoppingBag className="h-5 w-5 text-primary" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <h3 className="font-semibold truncate">{service.title || service.name}</h3>
                      {service.description && (
                        <p className="text-sm text-muted-foreground mt-1 line-clamp-2">
                          {service.description}
                        </p>
                      )}
                      <div className="flex flex-wrap gap-2 mt-3">
                        {service.category && (
                          <Badge variant="secondary" className="gap-1">
                            <Tag className="h-3 w-3" />
                            {service.category}
                          </Badge>
                        )}
                        <Badge variant="outline" className="gap-1">
                          <DollarSign className="h-3 w-3" />
                          {totalSpent.toLocaleString()} {service.currency || 'ALL'}
                        </Badge>
                      </div>
                      <div className="flex items-center gap-4 mt-3 text-xs text-muted-foreground">
                        <span>{invoiceCount} fatur├½</span>
                        {lastPurchase && (
                          <span>Blerje e fundit: {lastPurchase.toLocaleDateString('sq-AL')}</span>
                        )}
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </div>

      {/* Service Catalog */}
      <div>
        <h2 className="text-lg font-semibold mb-4">Katalogu i Sh├½rbimeve</h2>
        {allServices.length === 0 ? (
          <Card>
            <CardContent className="py-12 text-center">
              <p className="text-muted-foreground">Nuk ka sh├½rbime n├½ katalog</p>
            </CardContent>
          </Card>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {allServices.map(service => {
              const isPurchased = purchasedServiceDetails.some(p => p.service.id === service.id);
              return (
                <Card key={service.id} className={`transition-shadow hover:shadow-md ${isPurchased ? 'border-primary/30' : ''}`}>
                  <CardContent className="pt-6">
                    <div className="flex items-start justify-between gap-2">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <h3 className="font-semibold truncate">{service.title || service.name}</h3>
                          {isPurchased && (
                            <Badge className="bg-primary/10 text-primary text-xs">Aktiv</Badge>
                          )}
                        </div>
                        {service.description && (
                          <p className="text-sm text-muted-foreground mt-1 line-clamp-3">
                            {service.description}
                          </p>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center justify-between mt-4">
                      {service.category && (
                        <Badge variant="secondary" className="gap-1 text-xs">
                          <Tag className="h-3 w-3" />
                          {service.category}
                        </Badge>
                      )}
                      <span className="font-bold text-lg">
                        {service.price.toLocaleString()} {service.currency || 'ALL'}
                      </span>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      className="w-full mt-3 gap-1"
                      onClick={() => openQuestionnaire(service.category)}
                    >
                      <FileText className="w-3.5 h-3.5" />
                      K├½rko k├½t├½ sh├½rbim
                    </Button>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        )}
      </div>

      {/* Service Questionnaire Dialog */}
      <Dialog open={isQuestionnaireOpen} onOpenChange={(open) => {
        setIsQuestionnaireOpen(open);
        if (!open) setEditingInquiry(null);
      }}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {editingInquiry?.status === 'Draft' ? 'Vazhdo K├½rkes├½n' : editingInquiry ? 'Edito K├½rkes├½n' : 'Pyet├½sor p├½r Sh├½rbimin'}
            </DialogTitle>
          </DialogHeader>
          <ServiceQuestionnaireForm
            key={editingInquiry?.id || 'new'}
            onSubmit={handleQuestionnaireSubmit}
            preselectedService={preselectedService}
            prefillEmail={user?.email || ''}
            prefillName={user?.displayName || ''}
            initialDraft={editingInquiry ? { ...editingInquiry, id: editingInquiry.id } : undefined}
            onDraftSave={editingInquiry?.status === 'Draft' ? handleDraftSave : undefined}
            isEditing={!!editingInquiry && editingInquiry.status !== 'Draft'}
          />
        </DialogContent>
      </Dialog>

      {/* View Inquiry Detail Dialog */}
      <Dialog open={!!viewingInquiry} onOpenChange={(open) => { if (!open) setViewingInquiry(null); }}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Detajet e K├½rkes├½s</DialogTitle>
          </DialogHeader>
          {viewingInquiry && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <p className="text-xs text-muted-foreground">Biznesi</p>
                  <p className="font-medium">{viewingInquiry.businessName}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground">Kontakti</p>
                  <p className="font-medium">{viewingInquiry.contactName}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground">Email</p>
                  <p className="font-medium">{viewingInquiry.email}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground">Telefon</p>
                  <p className="font-medium">{viewingInquiry.phoneNumber}</p>
                </div>
              </div>
              {viewingInquiry.servicesInterestedIn && viewingInquiry.servicesInterestedIn.length > 0 && (
                <div>
                  <p className="text-xs text-muted-foreground mb-1">Sh├½rbimet e k├½rkuara</p>
                  <div className="flex flex-wrap gap-1">
                    {viewingInquiry.servicesInterestedIn.map(s => (
                      <Badge key={s} variant="secondary">{s}</Badge>
                    ))}
                  </div>
                </div>
              )}
              {viewingInquiry.mainGoal && (
                <div>
                  <p className="text-xs text-muted-foreground">Objektivi kryesor</p>
                  <p className="font-medium">{viewingInquiry.mainGoal}</p>
                </div>
              )}
              {viewingInquiry.projectNeedDescription && (
                <div>
                  <p className="text-xs text-muted-foreground">P├½rshkrimi i projektit</p>
                  <p className="text-sm">{viewingInquiry.projectNeedDescription}</p>
                </div>
              )}
              {viewingInquiry.budgetRange && (
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-xs text-muted-foreground">Buxheti</p>
                    <p className="font-medium">{viewingInquiry.budgetRange}</p>
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground">Afati</p>
                    <p className="font-medium">{viewingInquiry.timeline}</p>
                  </div>
                </div>
              )}
              <div className="pt-3 border-t">
                {viewingInquiry.status === 'New' && (
                  <Button size="sm" className="gap-1" onClick={() => { setViewingInquiry(null); openEditInquiry(viewingInquiry); }}>
                    <Edit3 className="w-3.5 h-3.5" />
                    Edito K├½rkes├½n
                  </Button>
                )}
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default PortalServicesView;
